export const PRODUCT = {

setup_and_security: {
  packages: ["core"],
  name: "Setup & Security",
  icon: "\u{1F512}",
  color: "#64748b",
  description: "Setup & Security is the foundation for configuring Public Sector Solutions users, constituent records, access controls, sharing, and audit capabilities. Person Accounts represent individual constituents, Contacts to Multiple Accounts supports relationships with multiple accounts, and profiles, roles, permission sets, permission set licenses, and permission set groups govern access across common features, licensing, inspections, benefits, social programs, provider management, investigative cases, talent recruitment, employee experiences, portals, analytics, data governance, AI, and Agentforce. Field Audit Trail supports longer retention of archived field history on enabled Public Sector Solutions objects. Salesforce Shield provides Shield Platform Encryption and Event Monitoring, while FedRAMP authorization is provided through Government Cloud offerings and the Hyperforce EU Operating Zone separately addresses European Union storage and processing.",
  components: [
    {id:"person-accounts",name:"Person Accounts",icon:"\u{1F464}",desc:"Person Accounts represent individual constituents in Public Sector Solutions by combining selected Account and Contact fields in one record. They support constituents who apply for licenses, permits, programs, benefits, grants, and services, while business accounts represent businesses. The standard Account object stores the person details, and Contacts to Multiple Accounts can associate one person account with multiple accounts without creating duplicate records.",tags:["PersonAccount","AccountAccountRelation"],docs:["Person accounts provide a simplified, customizable record for information about an individual constituent. They support duplicate management and single-step sharing, and they can relate to records such as cases, individual applications, and public complaints. Use the Person Account record type for individuals and business accounts for businesses. Account Contact Relation can associate an individual with multiple businesses.","Enable Person Accounts from Setup only after reviewing their effect in a sandbox because the feature can’t be turned off after activation. Before enabling it, verify that Account has at least one record type, profiles with Read access to Accounts also have Read access to Contacts, and the applicable Account and Contact sharing settings are configured. After activation, Salesforce creates the person account record type, which you assign to the appropriate user profiles.","Enable Contacts to Multiple Accounts when users must relate one constituent contact to multiple business, person, household, or group accounts. The account in the contact record’s Account Name field is the primary account and has a direct relationship; all other related accounts have indirect relationships. Add the Related Contacts related list to the Account page layout so users can view these relationships."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_task_admin_configure_person_acct.htm&type=5&language=en_US",connections:[{"planet":"licensing_and_permitting","desc":"Person accounts represent individual license applicants"},{"planet":"benefit_management","desc":"Person accounts are created for benefit applicants"},{"planet":"social_programs","desc":"Person accounts link to care plans and referrals"}]},
    {id:"profiles-and-permissions",name:"Profiles & Permission Sets",icon:"\u{1F511}",desc:"Profiles, roles, permission sets, permission set licenses, and permission set groups control how Public Sector Solutions users access data, features, and workflows. Profiles define baseline access, while roles limit access according to job responsibilities and the agency’s reporting structure. Permission sets and their associated licenses extend user access, and permission set groups bundle permissions by persona or job function.",tags:["PermissionSet","PermissionSetGroup"],docs:["Create profiles for intake officers, application reviewers, inspectors, compliance officers, recruiters, HR specialists, caseworkers, and other agency employees. Salesforce recommends cloning an existing profile, such as Standard User, and then customizing its permissions. Create roles that correspond to job responsibilities and arrange them in a role hierarchy so users can access data owned by or shared with roles below them when appropriate.","Permission sets provide access to objects and fields, custom metadata, and app and system settings. Some permission sets include permission set licenses, which extend the functionality of a Salesforce user license and are assigned automatically with the permission set; other permission set licenses are assigned directly. Users need the appropriate permission sets and permission set licenses to work with Public Sector Solutions features, and the available sets and licenses depend on the purchased solution and add-ons.","Permission set groups bundle permission sets by persona or job function and simplify consistent assignment, access auditing, and later updates. Public Sector Solutions includes groups for licensing and permitting officers and constituents, benefit caseworkers and constituents, social program caseworkers and providers, investigative case officers, talent recruitment users, employees, and administrators. Before assigning a group, verify that users have every required license and that gated org preferences are enabled; otherwise, permission set group calculation can fail."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_admin_concept_psc_permsets.htm&type=5&language=en_US",connections:[{"planet":"common_features","desc":"Permission sets control access to common layer components"},{"planet":"licensing_and_permitting","desc":"Public Sector Access permission set required for licensing objects"},{"planet":"inspections","desc":"Industries Visit permission set required for inspections"}]},
    {id:"field-audit-trail",name:"Field Audit Trail",icon:"\u{1F4DC}",desc:"Field Audit Trail extends the retention period for archived field history data on supported Public Sector Solutions objects. Agencies set field history retention policies to define how long historical field data is retained and managed in Salesforce. The supported objects include regulatory, relationship, application, benefit, case, inspection, recruitment, and program records.",tags:["FieldHistoryRetentionPolicy"],docs:["Use field history tracking to audit data changes and support strict data retention requirements. For objects that have Field Audit Trail enabled, configure field history retention policies to retain archived history for a longer period. The retention policy defines the period for retaining and managing the object’s historical field data.","Public Sector Solutions enables Field Audit Trail on a documented set of objects, including RegulatoryAuthority, BusinessType, AccountAccountRelation, ContactContactRelation, PartyRelationshipGroup, and PartyRoleRelation. It is also enabled on many application, benefit, case, inspection, regulatory, social program, and talent recruitment objects. Configure policies only for the enabled objects that your agency needs to audit."],connections:[{"planet":"licensing_and_permitting","desc":"Tracks changes to license applications and regulatory records"},{"planet":"benefit_management","desc":"Audits benefit assignment and disbursement changes"},{"planet":"inspections","desc":"Monitors inspection assessment and violation record changes"}]},
    {id:"shield-encryption",name:"Salesforce Shield",icon:"\u{1F6E1}",desc:"Salesforce Shield is an add-on that provides enhanced security features for protecting sensitive Public Sector Solutions data. Shield Platform Encryption protects sensitive data at rest while preserving supported application functionality, and Event Monitoring provides detailed performance, security, and usage data. FedRAMP authorization is provided through Government Cloud offerings, not Salesforce Shield, while the Hyperforce EU Operating Zone separately provides local storage and processing options in the European Union.",tags:["ShieldPlatformEncryption","EventMonitoring"],docs:["Shield Platform Encryption encrypts personally identifiable information and other sensitive, confidential, or proprietary data at rest. It supports external and internal data compliance policies while retaining critical application functionality such as search, workflow, and validation rules. Administrators retain control over encryption keys and can configure encrypted data permissions to protect information from unauthorized users.","Event Monitoring records interactions across Salesforce applications and makes detailed performance, security, and usage data accessible through APIs. Agencies can identify who accesses critical data, when and from where access occurs, review adoption, and troubleshoot performance. Event Monitoring data can be imported into visualization or application-monitoring tools such as Analytics, Splunk, or New Relic.","Government compliance is addressed separately from Salesforce Shield. Compliance for United States government agencies is achieved through Government Cloud offerings that have been granted FedRAMP authorization. In the European Union, the Hyperforce EU Operating Zone provides local storage and processing options and security measures intended to reduce regulatory risk and protect consumer data."],connections:[{"planet":"common_features","desc":"Shield protects data across all common layer components"},{"planet":"experience_cloud","desc":"Encryption extends to constituent-facing portal data"}]}
  ],
  dataFlow: ["Enable Person Accounts and Contacts to Multiple Accounts to support licensing and permitting, social program management, and other constituent-centered processes.","Create users, profiles, and role hierarchies, then assign permission sets, permission set licenses, and permission set groups for common features, inspectors, benefit caseworkers, social program users, providers, investigative caseworkers, recruiters, HR specialists, and employee users.","Configure organization-wide defaults and other sharing settings so authorized internal users and Experience Cloud portal users receive appropriate record access.","Set field history retention policies on Field Audit Trail enabled objects to preserve required audit history.","Configure Shield Platform Encryption and Event Monitoring to protect sensitive data and monitor Salesforce application activity, including activity that extends to constituent portals.","Grant administrative and feature permissions for Agentforce, Einstein AI, Data 360 governance and access controls, and CRM Analytics dashboards."],
  connections: [{"planet":"common_features","desc":"Security settings control access to common layer components"},{"planet":"licensing_and_permitting","desc":"Permission sets and person accounts required for licensing"},{"planet":"inspections","desc":"User roles and permissions control inspector access"},{"planet":"benefit_management","desc":"Permission set groups define caseworker access to benefits"},{"planet":"social_programs","desc":"Person accounts and permissions enable social program management"},{"planet":"experience_cloud","desc":"Shield and sharing settings extend to constituent portals"},{"planet":"provider_management","desc":"Permission configuration for provider network access"},{"planet":"investigative_cases","desc":"Security profiles for investigative caseworkers"},{"planet":"talent_recruitment","desc":"User profiles for recruiters and HR specialists"},{"planet":"agentforce","desc":"Agent configuration requires admin permissions"},{"planet":"einstein_ai","desc":"AI feature enablement and user permissions"},{"planet":"data_360","desc":"Data governance and access control policies"},{"planet":"crm_analytics","desc":"Analytics permission sets and dashboard access"},{"planet":"employee_experience","desc":"Employee user profiles and HR permissions"}]
},

common_features: {
  packages: ["core"],
  name: "Common Features",
  icon: "\u{1F9E9}",
  color: "#8b5cf6",
  description: "The Common Features domain is the no-code and low-code industry common layer that Public Sector Solutions uses across intake, assessment, delivery, and monitoring. It includes Action Plans, Business Rules Engine, Decision Explainer, document checklists, Dynamic Assessments built on Discovery Framework, Interaction Summaries, and OmniStudio components, with access governed by permission sets and permission set licenses. These capabilities automate license and grant review, benefit eligibility, inspections, social casework, social insurance intake, investigative work, talent evaluation, and emergency response coordination. OmniStudio components support Experience Cloud experiences, and Agentforce AI agents can use configured common features for supported automation.",
  components: [
    {id:"action-plans",name:"Action Plans",icon:"\u{1F4CB}",desc:"Action Plans provide repeatable sets of tasks and checklist items for business processes in Public Sector Solutions. Templates standardize recurring work, while individual plans can be assigned and adjusted for a specific application, visit, assessment, investigation, emergency response, grant, or constituent engagement. Task ownership, priority, and deadlines help reviewers, inspectors, caseworkers, and other team members coordinate work and monitor completion.",tags:["ActionPlan","ActionPlanTemplate","ActionPlanBaseTemplateAsgn","ActionPlanTemplateAssignment"],docs:["Action Plans contain tasks or checklist items used to track and automate processes with repeatable steps. Each task can have an owner, priority, and deadline, supporting collaboration among reviewers, inspectors, caseworkers, and other team members. Action Plan Templates define tasks for recurring processes, and users create plans from those templates for specific records. Plans can be customized as needed after creation when the template and configuration permit it.","Public Sector Solutions uses Action Plans for assessment questions and signature tasks in inspections and Dynamic Assessments, application review steps, benefit eligibility tasks, grant recipient due diligence, emergency program volunteer work, and preparation or follow-up for constituent meetings. Investigative Case Management uses plans as task lists and checklists during investigations. These uses allow the same planning mechanism to structure work across intake, assessment, delivery, and monitoring activities.","Internal users require the Action Plans permission set and access to the Action Plan, Action Plan Template, Document Checklist Item, and Recurrence Schedule objects. Experience Cloud users require corresponding object access and a permission set with the Action Plans feature permission enabled. Permission sets and permission set licenses control whether users can configure or work with these common-layer records."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_configure_use_action_plans.htm&type=5&language=en_US",connections:[{"planet":"inspections","desc":"Action plan templates define inspection visit tasks"},{"planet":"benefit_management","desc":"Action plans track benefit eligibility determination steps"},{"planet":"social_programs","desc":"Action plans support care plan task tracking"}]},
    {id:"business-rules-engine",name:"Business Rules Engine",icon:"\u{2699}",desc:"Business Rules Engine automates policy decisions and calculations in Public Sector Solutions. Its expression sets perform calculations and call decision matrices that match input values to rows and return defined outputs. Agencies use these rules for eligibility determinations, benefit amounts, application fees, licensing decisions, grant processes, and other policy-driven outcomes.",tags:["ExpressionSet","DecisionMatrix"],docs:["Business Rules Engine is a suite of services, components, and objects that performs calculations and automates policy decisions. It can determine whether applicants qualify for public programs and services and calculate amounts such as benefits or application fees from defined input criteria. This automation supports consistent processing for benefit eligibility, license application review, and grant-related workflows.","Expression sets are the calculation mechanism for business rules. They perform a sequence of calculations using variables, constants, and lookups to decision matrices. Decision matrices organize complex rules in tables, match input values to a row, and return that row’s output values. Expression sets and decision matrices accept JSON input from Omniscripts and return JSON output to them.","Administrators use the Rule Engine Designer permission to create decision matrices and expression sets, while runtime users require the appropriate Business Rules Engine permissions. Rules can be invoked from Omniscripts and flows to automate application intake and review. After a rule is configured, Decision Explainer can provide insight into the resulting calculation or determination."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_set_up_business_rules_engine.htm&type=5&language=en_US",connections:[{"planet":"benefit_management","desc":"Calculates benefit eligibility and amounts"},{"planet":"licensing_and_permitting","desc":"Automatically calculates application fees"},{"planet":"social_programs","desc":"Evaluates program eligibility criteria"}]},
    {id:"decision-explainer",name:"Decision Explainer",icon:"\u{1F4A1}",desc:"Decision Explainer provides transparency into calculations and determinations made by business rules in Public Sector Solutions. Its setup objects preserve metadata and logs that explain why a rule produced a specific result. Reviewers and constituents can use these explanations to understand application fees, eligibility decisions, benefit calculations, and other policy outcomes.",tags:["ExplainabilityActionDefinition","ExplainabilityActionVersion"],docs:["Decision Explainer is a collection of setup objects that provides insight into why a business rule generated a specific result. Public sector agencies can use it to support compliance, detect fraud, and promote equitable distribution of benefits. Documented examples include explanations for individual and business application fees, unemployment benefits, and housing loan eligibility checks.","For Business Rules Engine calculations, Decision Explainer can record the expression set, version, variables, values, and formulas associated with a decision. The Decision Explainer Log History component can be added to application Lightning record pages so reviewers can inspect decision history and open individual log entries. Public Sector Solutions also supports adding the Explainability Action Log component to Experience Cloud application pages so constituents can view explanations for supported records.","Configuration uses Application Subtype Definition, Business Process Type Definition, Explainability Action Definition, and Explainability Action Version records. An Omniscript expression set action can pass an explainability specification name and record context so that the resulting logs are associated with the application. Users who configure or use these entities require Decision Explainer Service Access, while site users require the applicable Decision Explainer permissions."],connections:[{"planet":"benefit_management","desc":"Explains benefit eligibility and amount decisions to constituents"},{"planet":"licensing_and_permitting","desc":"Shows reasoning behind fee calculations and license decisions"},{"planet":"experience_cloud","desc":"Decision explanations displayed on constituent portal"}]},
    {id:"document-management",name:"Document Management",icon:"\u{1F4C4}",desc:"Document Management in Public Sector Solutions uses Document Checklist Items to track supporting documents and route constituent submissions through approval workflows. Checklist items can be included in Action Plan Templates to make document collection and review repeatable. These capabilities support licensing and permitting, investigative cases, grants, benefits, and other application processes that require complete and reviewable documentation.",tags:["DocumentChecklistItem","DocumentType"],docs:["Document checklists route documents submitted by constituents through approval workflows. Administrators turn on Checklist Items with Attachments, assign the Document Checklist permission set, add Document Checklist Items to relevant application page layouts, and configure active document types. Experience Cloud profiles require Create access to Document Checklist Item when constituents upload checklist documents through a site.","Document Checklist Items can be added to Action Plan Templates so that each plan created from the template contains the required document items. This approach standardizes supporting-document collection for application review, grantmaking, and investigations. Published Action Plan Templates can’t be changed; administrators must create a new template when the checklist configuration must be revised.","Intelligent Document Automation can extract and store data from scanned or handwritten forms in records such as business license applications and individual applications. Reviewers can use the OCR Review component to compare extracted data with the source document and correct the captured values. Received documents can also be associated with records and selected Document Checklist Items, reducing manual data entry while retaining the submitted file for review."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_set_up_document_tracking_approvals.htm&type=5&language=en_US",connections:[{"planet":"licensing_and_permitting","desc":"Routes supporting documents for license applications"},{"planet":"benefit_management","desc":"Manages benefit application supporting documentation"},{"planet":"investigative_cases","desc":"Tracks evidence documents for investigative cases"}]},
    {id:"dynamic-assessments",name:"Dynamic Assessments",icon:"\u{1F4DD}",desc:"Dynamic Assessments provide conditional, guided evaluations for onsite and virtual inspections, investigations, benefit and program reviews, grant audits, and applicant evaluations in Public Sector Solutions. They are built on Discovery Framework and use Omni Assessment Task records to store assessment questions and the Omniscript logic that sequences them. Action Plans organize these tasks into repeatable checklists for inspectors, caseworkers, investigators, compliance officers, and hiring teams.",tags:["Assessment","AssessmentQuestion","OmniAssessmentTask","AssessmentIndicatorDefinition"],docs:["Discovery Framework is the data model for collecting information through Omniscript forms, and it forms the foundation of Dynamic Assessments. Assessment questions can be grouped by category or question set and configured with supported response data types. Omni assessment tasks contain the questions, while an Omniscript adds conditional logic so later questions can appear based on earlier responses.","Dynamic Assessments can be related to supported records such as business license applications, visits, cases, custody items, funding awards, application form evaluations, and vetting procedure evaluations. For regulatory assessments, questions can be related to regulatory codes and violation types. When the Fail value in Compliance Status is configured as a violation, selecting it for an assessment response can automatically create a regulatory code violation record.","Setup requires Discovery Framework, the Dynamic Assessment Access, Industries Assessment, Action Plans, and OmniStudio permissions, plus feature-specific access such as Industries Visit for onsite assessments. Administrators add Assessment List and Action Plan List components to relevant Lightning pages, create questions and omni assessment tasks, activate the resulting Omniscripts, and publish Action Plan Templates containing the tasks. Dynamic Assessments used in Talent Recruitment Management can evaluate applicants and vetting requirements, while inspections, benefit management, social casework, grantmaking, and investigative cases use the same framework for their respective evaluations.","Dynamic Assessments generally can't be exported and deployed between orgs through standard tools, but the documentation separately provides a Metadata API-based procedure for migrating them from sandbox to production or between orgs. Implementations should use that Metadata API migration path rather than assuming a simpler cross-org export is available."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_setup_use_dynamic_assessments.htm&type=5&language=en_US",connections:[{"planet":"inspections","desc":"Powers complex regulatory compliance evaluations during visits"},{"planet":"benefit_management","desc":"Captures applicant information for benefit eligibility assessment"},{"planet":"social_programs","desc":"Conducts complaint investigations and client assessments"}]},
    {id:"interaction-summaries",name:"Interaction Summaries",icon:"\u{1F4AC}",desc:"Interaction Summaries let caseworkers, case managers, and other Public Sector Solutions users capture detailed notes from meetings and conversations. The guided note flow supports rich text, next steps, attendees, files, sharing, and interest tags. Notes can be associated with cases, care plans, benefits, goals, complaints, referrals, and accounts to support social casework, investigations, and ongoing constituent service.",tags:["InteractionSummary","Interaction"],docs:["Interaction summaries provide a single guided flow for recording meetings and conversations with constituents or case participants. Users can enter detailed notes and next steps, identify attendees, attach relevant files, share notes, and categorize them with interest tags. The flow creates corresponding Interaction and Interaction Summary records for each interaction note.","The guided flow uses the activated AdvancedNotes/AddNote and AdvancedNotes/InterestTag Omniscripts. They work out of the box and can be cloned and customized when an agency requires different behavior. Administrators enable Interaction Summary and Enhanced Interaction Note Interface, add the Interaction Summaries component to relevant Lightning record pages, and configure topics and interest tags when users need note categorization.","Interaction summaries are private by default, and access can be expanded through sharing settings, parent object-level access, or Compliant Data Sharing. An approval process can be configured to review notes before publication. Publishing a note locks the related interaction summary, prevents further edits, and preserves the note for uses such as an official witness statement or evidence in an investigation."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_interaction_summaries_overview.htm&type=5&language=en_US",connections:[{"planet":"social_programs","desc":"Records caseworker interactions with constituents on care plans"},{"planet":"benefit_management","desc":"Documents benefit review meetings and phone conversations"},{"planet":"investigative_cases","desc":"Captures witness interviews and investigation notes"}]},
    {id:"omnistudio-integration",name:"OmniStudio Integration",icon:"\u{26A1}",desc:"OmniStudio Integration supplies no-code and low-code components for guided interactions and data movement in Public Sector Solutions. Omniscripts present responsive forms, Integration Procedures connect data and processes, Flexcards show contextual information, and Omnistudio Data Mappers read, transform, and write Salesforce data. These components power constituent portal experiences, social insurance claim intake, benefit applications, licensing forms, assessments, and other guided workflows.",tags:["OmniProcess","OmniProcessElement"],docs:["Omnistudio is a suite of components and services for creating guided applications and workflows with data from Public Sector Solutions and external sources. Omniscripts provide guided paths through business processes, Integration Procedures read and write data between Salesforce and external systems, Flexcards display contextual information and actions, and Omnistudio Data Mappers transform and persist Salesforce data. Public Sector Solutions includes Omniscript templates for processes such as business license applications and benefit applications, but the templates require customization for agency requirements.","During intake, Omniscripts can ask questions conditionally, populate fields with account or business profile data, accept supporting files, and let authenticated applicants save partially completed forms for later. Omnistudio Data Mappers can save submitted JSON data to records such as Business License Application or Individual Application. A Data Mapper and PDF Action can also transform a completed form into a PDF and attach it to the application record.","Omniscript components can be added to Experience Cloud pages so constituents can apply for licenses, permits, benefits, programs, and services. Public Sector Solutions also uses Omnistudio flows for social insurance claims, complaint intake, benefit recertification, changes of circumstances, provider referrals, and talent recruitment. Users require the appropriate OmniStudio Admin, OmniStudio User, or Experience Cloud permissions based on whether they design, run, or access these components."],connections:[{"planet":"licensing_and_permitting","desc":"Omniscripts power license and permit application flows"},{"planet":"benefit_management","desc":"OmniStudio drives benefit application intake and review flows"},{"planet":"experience_cloud","desc":"Omniscript components deploy to Experience Cloud sites"}]}
  ],
  dataFlow: ["Grant permission sets and licenses for the required common-layer components.","Capture licensing, benefit, social insurance, grant, complaint, and talent intake through OmniStudio-powered Experience Cloud experiences.","Apply Business Rules Engine, Decision Explainer, Document Checklist Items, and Dynamic Assessments to review applications and determine outcomes.","Create Action Plans and assessments for inspections, investigations, applicant evaluations, emergency response, and service delivery.","Record and publish Interaction Summaries for social casework and other constituent engagements.","Let Agentforce AI agents use configured common features to automate supported employee and constituent workflows."],
  connections: [{"planet":"setup_and_security","desc":"Permission sets control access to common layer components"},{"planet":"licensing_and_permitting","desc":"Common tools automate license application review and approval"},{"planet":"inspections","desc":"Action plans and assessments structure inspection visits"},{"planet":"benefit_management","desc":"BRE and assessments automate benefit eligibility determination"},{"planet":"social_programs","desc":"Interaction summaries and assessments support social casework"},{"planet":"experience_cloud","desc":"OmniStudio components power constituent portal experiences"},{"planet":"agentforce","desc":"Agentforce AI agents leverage common features for automation"},{"planet":"social_insurance","desc":"OmniStudio flows power social insurance claim intake"},{"planet":"investigative_cases","desc":"Action Plans and Document Checklists for investigations"},{"planet":"talent_recruitment","desc":"Dynamic Assessments used in applicant evaluation"},{"planet":"emergency_and_assets","desc":"Action Plans for emergency response coordination"},{"planet":"grantmaking","desc":"Business Rules Engine and Document Checklists for grants"}]
},

licensing_and_permitting: {
  packages: ["core"],
  name: "Licensing & Permitting",
  icon: "\u{1F4DC}",
  color: "#3b82f6",
  description: "Public Sector Solutions manages business and individual license and permit applications from guided intake through review, inspection, approval, and issuance. Agencies configure regulatory authorities, authorization types, business types, dependencies, training requirements, and transaction fees, while Business Rules Engine, Action Plans, and document capabilities automate processing. Experience Cloud supports constituent self-service, and inspections verify regulatory compliance before issuance. CRM Analytics, Agentforce, and Einstein AI provide licensing insights, processing assistance, constituent guidance, and review summaries, while the same application framework can support emergency permits and temporary authorizations.",
  components: [
    {id:"regulatory-authorities",name:"Regulatory Authorities",icon:"\u{1F3DB}",desc:"Regulatory Authorities represent the government agencies and departments responsible for issuing licenses and permits and enforcing related requirements. Each authority can oversee categories of regulatory authorizations for specific industries, occupations, or activities. These records provide the organizational foundation for configuring authorization types and regulatory compliance in Public Sector Solutions.",tags:["RegulatoryAuthority","RegulatoryAuthorizationType","BusinessType","BusRegAuthorizationType"],docs:["A Regulatory Authority record represents an issuing agency or department that defines and enforces regulatory requirements for licenses, permits, and independent inspections. Examples include a department of motor vehicles or a board that regulates barbering and cosmetology. Administrators create each authority with a name and description that identify its oversight responsibilities. Regulatory Authorization Type records can then reference the responsible authority.","Licensing and permitting setup requires users to have access to the relevant regulatory objects, typically through the Public Sector Access permission set. Agencies can add relevant related lists to application, account, business type, and authorization type page layouts to support regulatory workflows. Regulatory authority data can be created manually or imported in bulk with Data Loader. The same regulatory framework can support licensing, permitting, inspections, and regulatory code compliance."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_concept_admin_licensingandpermitting.htm&type=5&language=en_US",connections:[{"planet":"inspections","desc":"Regulatory authorities define inspection compliance standards"},{"planet":"common_features","desc":"Business Rules Engine automates regulatory determinations"}]},
    {id:"license-applications",name:"License Applications",icon:"\u{1F4E8}",desc:"License Applications capture requests from businesses or individuals for licenses and permits. Public Sector Solutions supports dynamic Omniscript forms, saved drafts, supporting documents, and Experience Cloud submission. Submitted applications can proceed through review, fee calculation, inspections, approval, and issuance while constituents track their progress through a self-service site.",tags:["BusinessLicenseApplication","IndividualApplication","PreliminaryApplicationRef"],docs:["Omniscripts provide guided, conditional application forms for licenses and permits. Omnistudio Data Mappers can populate forms with account and business profile information and save submitted data to Business License Application or Individual Application records. Applicants can upload supporting files, and a PDF Action can attach the completed form to the application record. Document Checklist Items can identify and route required supporting documents through review workflows.","Business License Application records store applicant and authorization information for requests from businesses. Authorization Application Asset maps an asset to an authorization application, while Authorization Application Place maps a location to an authorization application. These junction records relate to the application rather than to an issued Business License. Authorization Location Access Schedule records can capture access times for an application location.","The Licenses And Permits Experience Cloud site template provides pages where constituents can assess their needs, apply, renew, and view applications, inspections, fees, and issued licenses. When applicants save a partially completed Omniscript, Public Sector Solutions stores the session and creates a Preliminary Application Reference record. After submission, the final data is saved as a business license application or individual application. Compliance inspections can then be created from the application and completed before approval and issuance."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_create_record_type_for_each_license.htm&type=5&language=en_US",connections:[{"planet":"common_features","desc":"Document checklists and action plans manage application review"},{"planet":"inspections","desc":"Applications trigger inspection visits for compliance verification"},{"planet":"experience_cloud","desc":"Constituents submit applications through Experience Cloud portal"}]},
    {id:"authorization-types",name:"Authorization Types & Dependencies",icon:"\u{1F517}",desc:"Authorization Types & Dependencies define the licenses and permits required for particular businesses or individuals. Business Regulatory Authorization Type records map business types to Regulatory Authorization Types, and dependency records establish relationships and issuance order among required authorizations. Public Sector Solutions can also represent training and examination requirements for professional and occupational licenses.",tags:["BusRegAuthorizationType","BusRegAuthTypeDependency","RegAuthorizationTypeProduct"],docs:["A Regulatory Authorization Type represents a type of license or permit, such as a salon establishment license, sign permit, physician license, or vehicle registration. A Business Regulatory Authorization Type maps a Business Type to a Regulatory Authorization Type and establishes which authorization a business requires. A Business Regulatory Authorization Type Dependency connects a parent authorization mapping to a dependent mapping. Parent licenses or permits are issued before dependent child authorizations, while independent authorizations can be applied for separately.","The Permits component presents the licenses and permits required for a business type. On a Licenses And Permits Experience Cloud site, it shows all business regulatory authorization types and dependencies defined in the Public Sector Solutions org. Constituents can search by business type and review the resulting requirements and dependencies. This output is based on the business regulatory authorization type and dependency definitions, not on Regulatory Authorization Type Product relationships.","For professional and occupational licenses, agencies can configure Training Course, Course Offering, Examination, Training Course Participant, Person Education, and Person Examination information. Applicants can provide training, education, and examination details through a customized Omniscript. Omnistudio Data Mappers can create the related participant, education, or examination records when the form is submitted. These records support qualification review before a professional or occupational license is issued."],connections:[{"planet":"inspections","desc":"Authorization types determine required inspection types"},{"planet":"experience_cloud","desc":"Permits component shows required authorizations on portal"}]},
    {id:"regulatory-fees",name:"Regulatory Transaction Fees",icon:"\u{1F4B0}",desc:"Regulatory Transaction Fees represent charges associated with license and permit applications, inspections, and regulatory code violations. A parent fee stores its status, effective date and time, due date and time, and comments. Regulatory Transaction Fee Items divide the fee into individual amounts with their own statuses and optional comments.",tags:["RegulatoryTrxnFee","RegulatoryTrxnFeeItem"],docs:["Users can create a Regulatory Transaction Fee from the related list on a business license application or individual application. The parent fee identifies the account, status, effective date and time, due date and time, and optional comments. The due date belongs to the parent Regulatory Transaction Fee. Fee records can also support fees arising from inspection visits or violation enforcement actions.","A Regulatory Transaction Fee can contain multiple Regulatory Transaction Fee Items. For each item, users enter a name, fee amount, and optional comments, and the item can have its own status. Regulatory Transaction Fee Item does not contain a due-date field. Line items can represent charges such as an application fee, additional fee, or inspection fee.","Business Rules Engine can automate application fee calculations using expression sets and decision matrices. Rules can use inputs such as authorization category, authorization type, application category, establishment size, seating capacity, or location, depending on the configured calculation. Automation can also create a fee from an inspection visit or violation enforcement action. Decision Explainer can provide reviewers with the reasoning behind Business Rules Engine fee calculations."],connections:[{"planet":"inspections","desc":"Violations and enforcement actions generate regulatory fees"},{"planet":"common_features","desc":"Business Rules Engine calculates fee amounts automatically"},{"planet":"experience_cloud","desc":"Fee payment history displayed on constituent portal"}]},
    {id:"approval-process",name:"Approval Process",icon:"\u{2705}",desc:"The Approval Process component coordinates consistent review and approval of license and permit applications. Paths display application stages, queues distribute records to reviewers, and approval processes define submission, approval, rejection, and field-update actions. Reviewers can use approval components and hierarchical views to evaluate application records, documents, inspections, violations, enforcement actions, and fees.",tags:["ApprovalProcess"],docs:["A path provides a visual representation of application stages based on the Application Status field and the applicable application record type. A queue distributes submitted applications to available reviewers and can own the record while a queue member completes an approval step. An approval process defines entry criteria, assigned approvers, approval steps, final approval actions, and final rejection actions. Applications can move through statuses such as Submitted, Intake Complete, Ready for Inspection, Approved, and Issued according to agency configuration.","The Items to Approve component gives reviewers a centralized list of pending approval requests. From an approval request, reviewers can inspect supporting files, related visits, Authorization Application Places, and Authorization Application Assets before approving, rejecting, or reassigning the request. The Hierarchical View component can show nested application-related records, including visits, regulatory code violations, violation enforcement actions, and regulatory transaction fees. Approval History can also be exposed on application pages in an Experience Cloud site.","Action Plans can organize repeatable application review tasks, priorities, deadlines, and owners. Document Checklist Items and Intelligent Document Automation support the collection, extraction, routing, and review of application documents. Business Rules Engine and Decision Explainer support automated calculations and transparent decisions, while Einstein AI summaries and Agentforce can assist application review and processing. Required compliance inspections remain part of the approval lifecycle before a license is issued."],connections:[{"planet":"common_features","desc":"Action plans and record alerts support approval workflow steps"},{"planet":"setup_and_security","desc":"User roles and queues control reviewer assignment"}]},
    {id:"license-issuance",name:"License Issuance",icon:"\u{1F4C3}",desc:"License Issuance records the authorization granted after required application reviews and inspections are completed and approved. Authorized users create a Business License record with the holder, authorization type, business type, validity dates, and identifying information. Constituents can access issued licenses through the public portal, and agencies can provide a QR code that links to a license record.",tags:["BusinessLicense","AuthApplicationAsset","AuthApplicationPlace"],docs:["After all reviews and inspections are approved, an authorized user creates the Business License record in Public Sector Solutions. The user identifies the business owner or individual who holds the license and provides the applicable regulatory authorization type and business type details. The record also captures the license name, identifier, and validity period. Issued licenses are available from the Business Licenses related list on the holder’s account.","The Licenses And Permits Experience Cloud site can show constituents their issued licenses and permits alongside submitted applications and application drafts. An email template can include a QR code whose URL opens the corresponding Business License record. The recipient must have Read access to Business License records to open the record detail page. Authorization Application Asset and Authorization Application Place remain associated with the authorization application and do not establish asset or place relationships to the issued Business License."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_license_permit_site_prerequisites.htm&language=en_US&type=5",connections:[{"planet":"inspections","desc":"License issuance requires passing inspection results"},{"planet":"setup_and_security","desc":"Person accounts hold issued licenses in related lists"}]}
  ],
  dataFlow: ["Configure person accounts, business accounts, licensing user permissions, and required sharing settings.","Define regulatory authorities, authorization types, business-type mappings, dependencies, and emergency permits or temporary authorizations.","Publish guided application forms on an Experience Cloud site, and use Agentforce to assist constituents with licensing questions.","Route submitted applications through queues, paths, Action Plans, document review, Business Rules Engine calculations, and Einstein AI summaries.","Schedule and complete required compliance inspections, then review violations, enforcement actions, and fees before approval.","Issue the license, expose it for constituent self-service, and analyze licensing productivity and trends with CRM Analytics."],
  connections: [{"planet":"setup_and_security","desc":"Person accounts and permissions required for licensing workflows"},{"planet":"common_features","desc":"BRE, action plans, and documents automate application processing"},{"planet":"inspections","desc":"License applications require compliance inspections before issuance"},{"planet":"experience_cloud","desc":"Constituent portal enables self-service license applications"},{"planet":"crm_analytics","desc":"Analytics provides insights into licensing productivity and trends"},{"planet":"agentforce","desc":"AI agents assist with application processing and constituent questions"},{"planet":"einstein_ai","desc":"AI summaries for license application review"},{"planet":"emergency_and_assets","desc":"Emergency permits and temporary authorizations"}]
},

inspections: {
  packages: ["core"],
  name: "Inspections",
  icon: "\u{1F50D}",
  color: "#ef4444",
  description: "Public Sector Solutions manages regulatory inspections from code and checklist configuration through onsite Visit scheduling, violation recording, enforcement follow-up, and constituent-facing history. Fixed inspections use Action Plans and assessment indicators, while Dynamic Assessments add conditional logic and support onsite or virtual evaluations; inspections can verify license and permit applications, investigate social welfare complaints, or support emergency compliance checks. Inspection users work with Industries Visit and other applicable Public Sector permissions, while Business Rules Engine calculates fees associated with inspections or enforcement actions. Agentforce automates post-visit violation summaries and enforcement identification, Einstein provides the Prior Violation Report, Experience Cloud displays inspection history, and CRM Analytics provides insight into inspection trends and compliance performance.",
  components: [
    {id:"inspection-types-setup",name:"Inspection Types & Codes",icon:"\u{1F4CB}",desc:"Inspection Types & Codes defines the regulatory structure used by Public Sector Solutions inspections. Inspection Types correspond to inspection action plan templates for scenarios such as health and safety, food safety, cannabis dispensary establishment, and salon establishment inspections. Regulatory Codes define enforceable standards, while Assessment Indicator Definitions identify the conditions inspectors evaluate. Fixed inspections relate indicators and violation types through assessment indicator records, while Dynamic Assessments use question-version junctions for regulatory codes and violation types.",tags:["InspectionType","RegulatoryCode","RegulatoryCodeAssessmentInd","AssessmentIndicatorDefinition"],docs:["Administrators create Regulatory Code records for standards established by an authorized local, state or regional, or national government body. Each code can include a name, subject, description, type, effective dates, parent code, regulatory authority, and external reference URL. Regulatory Code Assessment Indicators relate these codes to Assessment Indicator Definitions so inspectors can view the applicable standard while evaluating a condition during an onsite inspection.","For fixed inspections, Assessment Indicator Definitions represent questions or conditions that inspectors evaluate and can use Boolean, picklist, text, and other supported field types. Assessment Task Definitions group those indicators into inspection checklists, and Action Plan Templates organize the tasks and optional signature tasks for a repeatable visit workflow. An Inspection Type corresponds to a published inspection action plan template, such as a salon establishment inspection template.","Dynamic Assessments use Discovery Framework assessment questions and Omni Assessment Tasks when an evaluation requires conditional logic. Regulatory Code Use records relate Assessment Question Versions to Regulatory Codes, and Violation Type Use records relate Assessment Question Versions to Violation Types. Examples such as Roof Inspection, Fire Safety Inspection, Electrical Inspection, and Solar Permit are assessment-question categories, not examples of Inspection Type records."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_admin_concept_configureinspections.htm&type=5&language=en_US",connections:[{"planet":"licensing_and_permitting","desc":"Regulatory codes define compliance standards for license types"},{"planet":"common_features","desc":"Assessment indicator definitions link to Dynamic Assessment questions"}]},
    {id:"visit-management",name:"Visit Management",icon:"\u{1F4C5}",desc:"Visit Management schedules and conducts onsite inspection visits in Public Sector Solutions. Compliance officers can create visits from license applications or public complaints, assign an inspector, specify a place, and associate a published action plan template. Salesforce Calendar presents visits as calendar events and uses user list views to help officers check inspector or caseworker availability. Inspectors conduct visits through the Inspection Management desktop or mobile app.",tags:["Visit","Visitor","InspectionAssessmentInd"],docs:["A Visit requires a location or address for the inspector to visit and can identify an account, inspection type, priority, context, planned start and end times, and special instructions. A compliance officer assigns the Visit to a Visitor and can relate it to a previous Visit through Parent Visit. Visits can be created from a license application, a public complaint, or a Visits list view, and complaint-driven visits support investigation of reported concerns, including social welfare concerns.","After the Visit is created, a published Action Plan Template is used to create an action plan for that specific inspection. The resulting assessment tasks and Inspection Assessment Indicator records provide the checklist that the inspector completes. The inspector starts and ends the Visit, records results, views related Regulatory Codes, uploads supporting images, adds notes, and captures a signature when required.","Salesforce Calendar can add Visits as calendar events and display user list views for checking the availability of inspectors and caseworkers before assignment. To create visits, locations, and action plans for visits, a user needs Industries Visit OR Public Sector Access OR Public Sector Field Access; inspection setup and user access can also require Industries Visit and Action Plans according to the user's responsibilities. During crisis-response processes, inspectors can use the Inspection app to verify that a site associated with an approved emergency permit complies with applicable health and safety ordinances."],connections:[{"planet":"licensing_and_permitting","desc":"Visits created from license application record pages"},{"planet":"common_features","desc":"Action plan templates define visit tasks and assessment steps"}]},
    {id:"violation-recording",name:"Violation Recording",icon:"\u{26A0}",desc:"Violation Recording captures noncompliance found during fixed inspections and Dynamic Assessments in Public Sector Solutions. Inspectors can create a Regulatory Code Violation manually or configure a failed assessment result to create one automatically. Each violation identifies the applicable Regulatory Code and can record severity, compliance status, the related Visit, and the date identified. Violation Types classify the conditions that represent failures to comply with regulatory standards.",tags:["RegulatoryCodeViolation","ViolationType","ViolationTypeAssessmentInd"],docs:["For fixed inspections, the Assessment Question Status field on Inspection Assessment Indicator includes values such as Pass, Fail, NA, and Issue. Administrators can mark Fail as a violation so that selecting it automatically creates a Regulatory Code Violation. Inspectors can also create a violation directly from the Regulatory Code Violations related list while completing a desktop or mobile inspection.","Violation Types define ways in which a business or site can fail to comply with a Regulatory Code and include a type, severity, and description. Violation Type Assessment Indicator relates a Violation Type to an Assessment Indicator Definition for fixed inspections. Dynamic Assessment questions instead use Violation Type Use records to relate Assessment Question Versions to Violation Types.","For Dynamic Assessments, administrators can similarly configure Fail on the Compliance Status field of Assessment Question Response as a violation. When the question is related to a Regulatory Code and Violation Type, Public Sector Solutions can create a Regulatory Code Violation from the failed response. Regulatory Code Violation records can also be followed through Chatter feed tracking and displayed with related records in Hierarchical View."],connections:[{"planet":"licensing_and_permitting","desc":"Violations affect license application approval decisions"},{"planet":"common_features","desc":"Dynamic Assessments auto-create violations on compliance failure"}]},
    {id:"enforcement-actions",name:"Enforcement Actions",icon:"\u{2696}",desc:"Enforcement Actions records compliance-officer follow-up for Regulatory Code Violations in Public Sector Solutions. After an inspection is complete, a compliance officer can create a Violation Enforcement Action from a violation found during the Visit. The action records its type, status, due date, and description, with documented examples including a citation or citation warning. Business Rules Engine can calculate fees associated with inspections or enforcement actions.",tags:["ViolationEnforcementAction"],docs:["A compliance officer reviews a completed Visit, selects a Regulatory Code Violation, and creates a Violation Enforcement Action from the related list. The officer selects an action type, such as Citation or Citation warning, and records the creation date and an optional due date. Approval processes can also be configured for Violation Enforcement Action records when agency review is required.","Public Sector Solutions uses Business Rules Engine to automate fee calculations associated with an inspection Visit or a Violation Enforcement Action. A decision matrix supplies lookup values, and an expression set performs calculations using those values and other variables. The resulting automation can create a Regulatory Transaction Fee; the documentation does not assign this fee calculation to Integration Procedures."],connections:[{"planet":"licensing_and_permitting","desc":"Enforcement actions generate regulatory transaction fees"},{"planet":"investigative_cases","desc":"Severe violations may escalate to investigative cases"}]},
    {id:"inspection-history",name:"Inspection History & Portal",icon:"\u{1F4CA}",desc:"Inspection History & Portal provides internal and constituent-facing views of inspection activity in Public Sector Solutions. The Inspection History component on an Experience Cloud site shows why an inspection was scheduled, observations from the Visit, and related violations or enforcement actions. Internal users can use Hierarchical View to review Visits, Regulatory Code Violations, Violation Enforcement Actions, and Regulatory Transaction Fees in context. Analytics and AI features provide additional insight into prior violations, inspection trends, compliance activity, and post-visit follow-up.",tags:["Visit","RegulatoryCodeViolation","ViolationEnforcementAction"],docs:["The Licenses And Permits Experience Cloud template includes a View Inspection History page with the Inspection History component. Constituents can use it to track inspections associated with their business, including the reason for an inspection, inspector observations, and violations or enforcement actions that require attention. Administrators can rename supported Regulatory Code Violation and Violation Enforcement Action field labels, with those changes also affecting the corresponding Public Sector Solutions record pages.","For internal review, Hierarchical View can present related records without requiring users to navigate multiple tabs. Configurations can show Visits, their Regulatory Code Violations, related Violation Enforcement Actions, and Regulatory Transaction Fees from account, application, complaint, or Visit pages. CRM Analytics provides Compliance Insights, Department Summary, Executive Summary, and Account Insights dashboards for inspection trends, violations, enforcement activity, and compliance performance.","Einstein generative AI provides the Prior Violation Report on a Visit record, summarizing Regulatory Code Violations from previous inspection visits and the status of related Violation Enforcement Actions. Agentforce Compliance Management can review policy documents after a Visit, identify and summarize violations, suggest enforcement actions and penalty fees, and email details to the business owner. These capabilities support post-visit administration while leaving compliance officers responsible for reviewing the resulting information and actions."],connections:[{"planet":"experience_cloud","desc":"Inspection history displayed on constituent portal"},{"planet":"licensing_and_permitting","desc":"Hierarchical view shows inspection chain on license applications"}]}
  ],
  dataFlow: ["Define Regulatory Codes, Assessment Indicator Definitions, Inspection Types, Violation Types, and reusable Action Plans or Dynamic Assessments.","Create onsite Visits for license and permit compliance, social welfare complaints, public complaints, or emergency-permit inspections.","Assign inspectors, schedule Visits in Salesforce Calendar, and grant the applicable Industries Visit, Public Sector Access, or Public Sector Field Access permissions.","Conduct fixed-checklist onsite inspections, or use Dynamic Assessments for conditional onsite or virtual evaluations.","Record failed results as Regulatory Code Violations, review Agentforce findings, create enforcement actions, and calculate applicable fees with Business Rules Engine.","Publish inspection history through Experience Cloud, generate Einstein summaries and reports, and analyze inspection trends and compliance rates with CRM Analytics."],
  connections: [{"planet":"licensing_and_permitting","desc":"Inspections verify compliance for license and permit applications"},{"planet":"common_features","desc":"Action plans and Dynamic Assessments structure inspection workflows"},{"planet":"setup_and_security","desc":"Industries Visit permission set required for inspection users"},{"planet":"experience_cloud","desc":"Inspection history component displays on constituent portal"},{"planet":"social_programs","desc":"Complaints trigger inspection visits to investigate welfare concerns"},{"planet":"agentforce","desc":"AI agent automates post-visit summaries and enforcement identification"},{"planet":"crm_analytics","desc":"Analytics provides insights into inspection trends and compliance rates"},{"planet":"einstein_ai","desc":"AI-generated inspection summaries and reports"},{"planet":"emergency_and_assets","desc":"Emergency inspections during crisis events"}]
},

social_programs: {
  packages: ["core"],
  name: "Social Programs",
  icon: "\u{1F91D}",
  color: "#f59e0b",
  description: "Social Programs in Public Sector Solutions manages nonfinancial social services for individuals and families facing hardship through programs, enrollments, benefits, goals, referrals, complaints, and individualized care plans. Assessments, action plans, and interaction summaries support social casework, while financial assistance from Benefit Management complements these services and person accounts and permissions enable authorized program management. Constituents can file complaints and referrals through Experience Cloud; complaints can require inspection visits or escalate to investigative cases, and care plans can include referrals to external service providers. Emergency Program Management and Grantmaking are separate features that extend service and benefit delivery for crisis response and community needs.",
  components: [
    {id:"programs-and-enrollment",name:"Programs & Enrollment",icon:"\u{1F4D6}",desc:"Programs & Enrollment defines the nonfinancial social care programs that agencies provide to individuals and families facing hardship. Programs can address areas such as job readiness, youth development, refugee settlement, housing services, and child welfare, with related benefits representing specific services such as counseling, workshops, and training. Eligible constituents are enrolled in programs, while benefits are assigned separately through the Benefit Assignment object.",tags:["PublicProgram","ProgramEnrollment","Benefit","BenefitType"],docs:["Programs and benefits are the foundation of Social Program Management in Public Sector Solutions. Agencies define high-level programs that support constituents’ social, physical, and emotional well-being, and then create related benefits for the services delivered under each program. Program records can be categorized and managed by status and effective dates to reflect the period in which services are available.","Program enrollment and benefit assignment are distinct parts of the documented model. Caseworkers enroll eligible constituents in programs and separately use the Benefit Assignment object to assign services or other benefits. A ProgramEnrollment record connects a constituent to a program and can associate the enrollment with a care plan, but it does not itself assign benefits.","Emergency Program Management and Grantmaking are separate Public Sector Solutions features that extend crisis assistance and grant-funded services beyond core Social Program Management. Financial benefit assistance from Benefit Management can complement the nonfinancial services managed here. Person accounts represent individual constituents, and the applicable permission sets or permission set groups provide caseworkers and constituents with access to program management features."],connections:[{"planet":"benefit_management","desc":"Financial benefit programs complement social program services"},{"planet":"common_features","desc":"Action plans track enrollment and program delivery tasks"}]},
    {id:"goals-and-outcomes",name:"Goals & Outcomes",icon:"\u{1F3AF}",desc:"Goals & Outcomes defines the objectives that programs and care plans are intended to help constituents achieve. Goal definitions can form a hierarchy of top and intermediate goals, while goal assignments track an individual goal within a care plan. Outcome Management can evaluate whether programs achieve their intended outcomes and support action based on collected data and progress.",tags:["GoalDefinition","GoalAssignment"],docs:["Goal definitions provide reusable objectives for programs and care plans. Public Sector Solutions supports hierarchical goals, such as a top goal for a unified household with intermediate goals for emotional safety and financial stability. Benefits can be associated with goal definitions so that assigned services support a defined objective.","A GoalAssignment applies a goal definition to a care plan and tracks its status, target date, and completion date. Caseworkers can use Dynamic Assessments to evaluate a constituent’s progress toward goals and positive outcomes. Interaction Summaries can also capture meeting notes, next steps, attendees, and supporting files in the context of goals.","Outcome Management extends goal-based casework by helping agencies define an impact strategy, collect data, track progress, and evaluate program effectiveness. Agencies can use the resulting insights to determine whether programs are being delivered as planned and whether they achieve their intended outcomes. The documentation gives examples such as tracking shelter received through a housing grant or academic progress in publicly funded early childhood programs."],connections:[{"planet":"common_features","desc":"Interaction summaries document goal progress conversations"},{"planet":"einstein_ai","desc":"AI insights help assess program effectiveness and outcomes"}]},
    {id:"care-plans",name:"Care Plans",icon:"\u{1F4C2}",desc:"Care Plans provides individualized plans for delivering social program services and benefits to constituents. Caseworkers can create plans from standardized templates containing goals and benefits, and then tailor them to a constituent’s circumstances. Care plans combine long-term or intermediate goals with concrete action plans intended to support positive outcomes.",tags:["CarePlan","CarePlanTemplate","CarePlanTemplateBenefit","CarePlanTemplateGoal"],docs:["Caseworkers create care plans after intake screening and findings from a Dynamic Assessment establish the constituent’s needs. A care plan provides a structured way to coordinate support services, assigned benefits, and goals for an individual or family. Public Sector Solutions supports Dynamic Assessments based on the Care Plan object to assess the need for a plan and evaluate progress over time.","Care plan templates provide a standardized starting point for recurring circumstances. CarePlanTemplateBenefit records add benefits to a template, while CarePlanTemplateGoal records add goal definitions; caseworkers can then add or remove benefits and goals to address the client’s unique situation. Action plans can supply repeatable tasks, questions, and next steps associated with delivering and monitoring care.","Care plans can include referrals to external service providers when an agency relies on a provider network to deliver services. Provider Search helps caseworkers find providers and facilities offering the required benefits, and the Provider Referral guided flow creates and shares referrals with selected providers. Interaction Summaries, Life Events and Milestones, and Timeline provide additional context for planning services and monitoring the constituent’s progress."],connections:[{"planet":"common_features","desc":"Dynamic Assessments inform care plan creation decisions"},{"planet":"provider_management","desc":"Care plans include referrals to service providers"},{"planet":"benefit_management","desc":"Care plans assign monetary benefits to eligible participants"}]},
    {id:"referral-intake",name:"Case Referral Intake",icon:"\u{1F4E9}",desc:"Case Referral Intake helps intake agents screen requests from public agencies, providers, and partner organizations and create cases for constituents who need support. Case managers can prioritize accepted cases and hand them to caseworkers for assessment and service assignment. Referrals can also support provider authorization and collaboration when constituents are directed to external organizations.",tags:["Referral","Case"],docs:["Referral needs often arise after events such as job loss, eviction, or the death of a spouse. Intake agents use Case Referral Intake to screen requests and identify needs such as job training, temporary housing, nutrition education, meal delivery, or transportation services. Case managers then prioritize cases and assign them to caseworkers for further assessment.","Omnistudio supports guided referral intake forms, and Public Sector Solutions includes a referral intake template that agencies can customize. Constituents can submit referrals through an Experience Cloud site when the site, profiles, permissions, and sharing settings are configured. Action Launcher can also place referral intake alongside other frequently used actions on a person account or other record page.","Referral processing also connects social casework with Provider Management. After identifying the services a constituent needs, a caseworker can use Provider Search and the Provider Referral guided flow to create a referral for each selected provider and relate it to the constituent, case, and provider. A provider can request authorization, and a caseworker can authorize the referral so the provider can proceed with service delivery."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_admin_constituent_relationships.htm&type=5&language=en_US",connections:[{"planet":"provider_management","desc":"Referrals connect constituents with service providers"},{"planet":"common_features","desc":"OmniScript guided flows capture referral intake details"}]},
    {id:"complaint-processing",name:"Complaint Management",icon:"\u{1F4E2}",desc:"Complaint Management captures and processes reports concerning a person’s health, safety, or well-being. Guided intake and Dynamic Assessments help staff record incident details, evaluate allegations and severity, and determine follow-up actions. A complaint can lead to a support case, an inspection visit, or an investigative case when further inquiry is required.",tags:["PublicComplaint","ComplaintCase","ComplaintParticipant"],docs:["Constituents and legally mandated reporters can file complaints online, while intake agents can capture complaints by phone or at an agency office. The complaint intake guided flow records critical information, including the people involved, their roles, and the nature of the issue, and saves the information in a PublicComplaint record. Experience Cloud sites can expose complaint filing and complaint lists to constituents with the required profile, object, and sharing access.","Caseworkers can conduct a Dynamic Assessment to evaluate the allegations, complaint severity, and appropriate response. The complaint intake flow itself is based on a Dynamic Assessment, and additional assessments can determine whether affected individuals need programs, benefits, or a care plan. Interaction Summaries can preserve detailed notes about complaint-related meetings and conversations.","A complaint reviewer can create a standard case to provide support or an investigative case for further inquiry. When a reported concern requires an onsite investigation, staff can create an inspection visit from the complaint and review related regulatory code violations or violation enforcement actions. Public Sector Solutions also supports compliant data sharing for Public Complaint records and complaint participants when sensitive information must be shared with authorized users."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_admin_case_management.htm&type=5&language=en_US",connections:[{"planet":"inspections","desc":"Complaints may trigger inspection visits to investigate concerns"},{"planet":"investigative_cases","desc":"Screened complaints can escalate to investigative cases"},{"planet":"common_features","desc":"Guided intake flows and assessments support complaint processing"}]}
  ],
  dataFlow: ["Configure person accounts and permissions, then define social programs, goals, benefits, care plan templates, emergency assistance, and grant-funded services.","Receive complaints and referrals through Experience Cloud or staff intake, and use assessments, action plans, and interaction summaries to document the circumstances.","Screen referrals and complaints, schedule inspection visits when needed, and escalate qualifying complaints to investigative cases.","Create a personalized care plan, assign goals and action items, and make referrals to external service providers.","Enroll the constituent in the selected program, then assign benefits separately through Benefit Assignment and complement social services with financial benefit assistance when appropriate.","Monitor enrollments, goals, outcomes, and service delivery, and link relevant social insurance claims, emergency assistance, and grant-funded benefit delivery."],
  connections: [{"planet":"common_features","desc":"Assessments, action plans, and interaction summaries power social casework"},{"planet":"benefit_management","desc":"Financial benefit assistance complements social program services"},{"planet":"setup_and_security","desc":"Person accounts and permissions enable program management"},{"planet":"inspections","desc":"Complaints may require inspection visits for investigation"},{"planet":"investigative_cases","desc":"Complaints escalate to investigative cases when needed"},{"planet":"provider_management","desc":"Care plans include referrals to external service providers"},{"planet":"experience_cloud","desc":"Constituents file complaints and referrals through portal"},{"planet":"social_insurance","desc":"Social insurance claims link to program enrollment"},{"planet":"emergency_and_assets","desc":"Emergency assistance programs for crisis response"},{"planet":"grantmaking","desc":"Grant-funded programs and benefit delivery"}]
},

benefit_management: {
  packages: ["core"],
  name: "Benefit Management",
  icon: "\u{1F4B5}",
  color: "#10b981",
  description: "Benefit Management in Public Sector Solutions supports monetary assistance for eligible individuals, families, and organizations through benefits such as social insurance, tax benefits, subsidies, food and housing assistance, and direct cash assistance. It combines Experience Cloud self-service, OmniStudio and assessment-based intake, Business Rules Engine eligibility and amount calculations, benefit assignment, flow-generated disbursements, changes of circumstances, and periodic recertification; permission set groups define caseworker and constituent access. Social programs and care plans connect to assignments, social insurance adds policy-based enrollment, provider networks deliver assigned services after referral authorization, Employee Experience applies benefit capabilities to employees alongside HR Service, and Grantmaking supports grant-funded programs and disbursements. Data 360 unifies constituent eligibility data, Einstein capabilities assist eligibility review and summarize case notes, and CRM Analytics provides insights into caseloads, community impact, and benefit distribution.",
  components: [
    {id:"benefit-types-config",name:"Benefit Types & Configuration",icon:"\u{2699}",desc:"Benefit Types & Configuration defines the programs, benefit types, benefits, eligibility criteria, and recertification timelines used in Public Sector Solutions. Administrators enable Program and Benefit Management and Benefit Disbursement Settings before configuring benefit records and related automation. Benefit Item Code records can map benefits to Code Set or Code Set Bundle records for provider-supported service variations.",tags:["BenefitType","Benefit","BenefitItemCode"],docs:["Public Sector Solutions uses Program, Benefit Type, and Benefit records to define monetary assistance such as social insurance, tax benefits, subsidies, food and housing assistance, and direct cash assistance. A benefit identifies the assistance offered through a program, while its benefit type classifies the benefit. Administrators enable Create and manage your programs, benefits, and goals and Create and manage benefit disbursements before configuring these records.","Eligibility criteria can consider age, income, expenses, household size, and other constituent information. Decision matrices and expression sets represent the rules used for prescreening, eligibility determinations, and benefit amount calculations. Because sample eligibility criteria and formulas must be adapted to applicable laws and regulations, agencies remain responsible for how they configure and use these rules.","Benefits that require periodic review can specify Recertification Frequency and Start Recertification From values. These values determine how often constituents must recertify and when they can begin the recertification process before the due date. For provider-delivered services, Benefit Item Code records map a benefit to a Code Set or Code Set Bundle that represents distinct services or benefit variations."],connections:[{"planet":"social_programs","desc":"Benefits link to programs and goal definitions for outcomes tracking"},{"planet":"common_features","desc":"Business Rules Engine references benefit types for eligibility rules"}]},
    {id:"benefit-application-intake",name:"Application Intake",icon:"\u{1F4E5}",desc:"Application Intake captures benefit applications and supporting information through guided constituent and caseworker experiences. Public Sector Solutions uses Discovery Framework assessment questions, Omniscripts, Omnistudio Integration Procedures, and Omnistudio Data Mappers to collect and store application data. Experience Cloud provides self-service application pages, saved sessions, document uploads, and application status visibility.",tags:["IndividualApplication","Assessment","AssessmentQuestion"],docs:["The Benefit Assistance Experience Cloud site lets constituents search for benefits, apply for assistance, view applications, report changes of circumstances, and recertify. Omniscripts provide guided forms, and applicants can save partially completed forms for later when that option is configured. Submitted forms create Individual Application records, while uploaded evidence can be managed with Document Checklist Items.","The recommended benefit application intake process is based on Discovery Framework. Assessment questions collect standardized information about applicants, household members, income, expenses, and other eligibility factors, and responses are stored in assessment records. Omnistudio Integration Procedures and Omnistudio Data Mappers move the collected data into Salesforce objects and can preserve effective start and end dates for income and expense information.","Public Sector Solutions provides a benefit management Discovery Framework template with assessment questions, Omniscripts, Integration Procedures, and Data Mappers for a sample Low Income Home Energy Assistance Program process. Administrators customize these components for their own benefit programs and activate the required Integration Procedures and Omniscripts. A screening trigger can call ProcessIndividualApplicationForBenefits after submission to deny applications that fail configured checks or place qualifying applications in review."],connections:[{"planet":"common_features","desc":"Discovery Framework and OmniStudio power application forms"},{"planet":"experience_cloud","desc":"Benefit Finder and application forms on constituent portal"}]},
    {id:"eligibility-determination",name:"Eligibility Determination",icon:"\u{2696}",desc:"Eligibility Determination applies configured policy rules to application and household information. Business Rules Engine uses decision matrices and expression sets to determine eligibility and calculate qualified benefit amounts. Decision Explainer provides transparency into the inputs, rules, and calculations behind those results.",tags:["ExpressionSet","DecisionMatrix"],docs:["Business Rules Engine automates policy decisions and benefit calculations through decision matrices and expression sets. Decision matrices match input values, such as household size or income, to configured outputs, while expression sets combine lookups, variables, conditions, and calculations. The eligibility assessment and benefit application flows invoke these rules during prescreening and application processing.","Public Sector Solutions provides templates for prescreening, household-member eligibility, and benefit amount calculations. Administrators create and activate the required decision matrices, save expression sets from the supplied templates, and configure effective dates and ranks for expression set versions. The benefit application review flow lets caseworkers check eligibility, view calculation variables, change a value for simulation, and see how updated application details affect the result.","Decision Explainer records the reasoning behind Business Rules Engine determinations and calculations. Agencies can configure explainability message templates and explainability action definitions so caseworkers and constituents can understand eligibility and benefit amount decisions. Data 360 can unify eligibility data from multiple systems, while Einstein-generated application and household summaries help caseworkers review circumstances and changes relevant to eligibility."],connections:[{"planet":"common_features","desc":"BRE and Decision Explainer automate and explain eligibility decisions"},{"planet":"experience_cloud","desc":"Eligibility prescreening available on constituent portal"}]},
    {id:"benefit-assignment",name:"Benefit Assignment",icon:"\u{1F4CB}",desc:"Benefit Assignment records the benefit approved for an eligible applicant, including its amount, frequency, status, and applicable dates. Assignments can be created through the benefit application review guided flow or entered manually. Social programs and care plans connect benefits to constituent goals, while provider workflows use existing assignments to coordinate service delivery.",tags:["BenefitAssignment","BenefitAssignmentAdjustment","BenefitScheduleAssignment"],docs:["After a caseworker confirms that an application is complete and the applicants are eligible, the benefit application review guided flow creates a Benefit Assignment and changes the application status to Approved. The caseworker selects the benefit, specifies payout start and end dates, enters the total approved amount, and selects the payout frequency. A benefit can also be assigned manually by selecting the applicable benefit, program enrollment, individual application, dates, entitlement amount, remaining amount, and next payout date.","Social Program Management uses programs, benefits, goals, and care plans to support constituents. Caseworkers can create personalized care plans, enroll clients in programs, and assign benefits that address identified needs. Social Insurance also uses Benefit Assignment to assign eligible benefits after claims and policy-based processes are completed.","Provider referrals occur after the caseworker creates the care plan, goal assignments, and benefits and determines which services the constituent needs. Provider Search finds suitable providers, and the provider referral guided flow creates referral records related to the case, constituent account, and provider; it does not itself assign the benefit. When a caseworker authorizes a referral, the Authorize Referral for Provider flow shares the benefit assignment related to the referral and the enrollee account with the provider user."],connections:[{"planet":"social_programs","desc":"Care plans trigger benefit assignment to enrolled constituents"},{"planet":"common_features","desc":"Caseworker guided flow processes assignment and adjustments"}]},
    {id:"benefit-disbursement",name:"Benefit Disbursement",icon:"\u{1F4B8}",desc:"Benefit Disbursement tracks the amount, date, status, and quantity delivered against a Benefit Assignment. Public Sector Solutions can generate disbursement records with a schedule-triggered flow for upcoming payments or with a case-specific flow. Disbursements also support provider service tracking and can be passed into outbound payment and accounting processes.",tags:["BenefitDisbursement","BenefitDisbursementAdj","BenefitSchedule","BenefitSession"],docs:["Public Sector Solutions includes the Create Disbursements and Adjustments schedule-triggered flow for generating benefit disbursements at a configured frequency, including large volumes of records. Administrators configure the flow start date, start time, and frequency before activation. For individual cases, the Create Disbursement flow can generate a disbursement for a specified Benefit Assignment, although the scheduled approach is recommended.","Provider-delivered benefits use disbursements to track service delivery. After an authorized referral, a provider can create a schedule, submit it for approval, and enroll the constituent in approved benefit sessions. Each session enrollment creates a Benefit Disbursement, and attendance updates the related record with attendance status and disbursed quantity.","Accounting Subledger can map benefit disbursement transactions to accounting objects and make the data available to an accounting system through reports or integration. Outbound Payments can generate payment instructions when a Benefit Disbursement is created, send those instructions to an Enterprise Resource Planning system, and reconcile completed transactions returned to Salesforce. Grantmaking separately supports grant disbursements, while the outbound payment framework centralizes transaction tracking across benefit programs, social insurance, and provider management."],connections:[{"planet":"social_insurance","desc":"Disbursement engine shared with social insurance payments"},{"planet":"common_features","desc":"Notification flows alert constituents of disbursement status"}]},
    {id:"benefit-recertification",name:"Recertification & Changes",icon:"\u{1F504}",desc:"Recertification & Changes manages circumstances that can alter a constituent’s continued eligibility or benefit amount. Guided Experience Cloud flows let constituents report changes and periodically recertify by reviewing prior information, updating details, and uploading supporting documents. Caseworkers review the resulting Individual Application records and renew, adjust, accept, or deny benefits as appropriate.",tags:["IndividualApplication","BenefitAssignment"],docs:["The change of circumstances flow lets constituents report personal, household, or financial changes that can affect benefits or services. Constituents select the changes to report, review previously provided details, update household and income information, upload supporting documents, and submit the application. The flow creates an Individual Application that a caseworker reviews before accepting or denying the reported changes.","When an accepted change affects an assigned benefit, Public Sector Solutions can create a benefit assignment adjustment application for the caseworker to process. The review flow compares the new entitlement amount with the current assignment and creates a Benefit Assignment Adjustment with the adjustment amount and effective dates. This preserves the connection between the reported circumstance, the review application, and the resulting change to the assigned benefit.","For periodic recertification, administrators define Recertification Frequency and Start Recertification From on each benefit. Data Processing Engine definitions add recertification due dates and identify assignments that are Pending or Lapsed, while application processing can update an assignment to In Progress and then Recertified. After reviewing an accepted recertification application, a caseworker can create an adjustment for a changed amount or use a zero adjustment amount to renew the assignment for the selected date range."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_benefit_assistance_comm_settings.htm&language=en_US&type=5",connections:[{"planet":"experience_cloud","desc":"Recertification and change of circumstances flows on portal"},{"planet":"common_features","desc":"Data Processing Engine and OmniStudio power recertification workflows"}]}
  ],
  dataFlow: ["Configure programs, benefit types, benefits, eligibility rules, recertification timelines, and Benefit_Management_Caseworker and Benefit_Management_Constituent access; extend eligible offerings through social insurance policies, employee benefit experiences, and grant-funded programs.","Publish self-service benefit discovery and application flows through Experience Cloud, and collect household, financial, and supporting information with OmniStudio and assessments while using Data 360 to unify constituent eligibility data.","Evaluate submitted applications with Business Rules Engine, use Decision Explainer to expose decision logic, and apply Einstein-assisted summaries and case notes to support eligibility review.","Assign approved benefits through Individual Applications and connect them to social programs and care plans; search provider networks and create provider referrals from a case, referral, or existing benefit assignment, then authorize sharing of the related record with the selected provider.","Generate Benefit Disbursement records with scheduled or case-specific flows, track provider-delivered sessions and quantities, and coordinate applicable social insurance, accounting, and outbound payment processes (grant disbursements are handled separately by Grantmaking).","Process changes of circumstances and recertification applications, create Benefit Assignment Adjustment records when needed, and use CRM Analytics to monitor caseloads and benefit distribution."],
  connections: [{"planet":"common_features","desc":"BRE, assessments, and OmniStudio automate benefit workflows"},{"planet":"social_programs","desc":"Social programs and care plans connect to benefit assignment"},{"planet":"setup_and_security","desc":"Permission set groups define caseworker and constituent access"},{"planet":"experience_cloud","desc":"Constituent portal enables self-service benefit applications"},{"planet":"social_insurance","desc":"Social insurance extends benefit management with policy-based enrollment"},{"planet":"provider_management","desc":"Provider networks deliver assigned benefit services"},{"planet":"crm_analytics","desc":"Analytics provides insights into benefit distribution and caseloads"},{"planet":"einstein_ai","desc":"AI-assisted eligibility determination and case notes"},{"planet":"data_360","desc":"Unified constituent data for benefit eligibility"},{"planet":"employee_experience","desc":"Employee benefits through HR service integration"},{"planet":"grantmaking","desc":"Grant-funded benefit programs and disbursements"}]
},

social_insurance: {
  packages: ["core"],
  name: "Social Insurance",
  icon: "\u{1F3E5}",
  color: "#06b6d4",
  description: "Social Insurance in Public Sector Solutions supports programs typically funded through regular employee (including self-employed) contributions, with employers also contributing depending on the program, protecting constituents from economic hardship caused by retirement, workplace injury, illness, and similar life events. It covers policy definition, constituent enrollment, contribution tracking, claim intake, review, approval, support planning, benefit assignment, and disbursement. Workers’ compensation flows use Omniscripts on a Benefit Assistance Experience Cloud site, while Discovery Framework stores claim intake responses in assessment records related to an Individual Application. The domain also identifies barriers to care and supports referrals to providers that can deliver needed services.",
  components: [
    {id:"insurance-policies",name:"Insurance Policies",icon:"\u{1F4DC}",desc:"Insurance Policies defines social insurance policies that protect eligible constituents from economic hardship caused by events such as retirement, workplace injury, or illness. Public Sector Solutions relates constituents’ person accounts to policies to manage enrollment and uses Insurance Policy Transaction records to track contributions. Payment Request and Payment Request Line records capture required contributions from constituents or employers. The underlying social insurance programs and benefits are configured with Program, Benefit Type, and Benefit records.",tags:["InsurancePolicy","InsurancePolicyTransaction","Program","BenefitType","Benefit"],docs:["Public Sector Solutions uses the Insurance Policy object to define social insurance policies and relate enrolled constituents’ person accounts to them. Insurance Policy Transaction records track contributions to a policy. These contributions can include regular payments from employees, self-employed individuals, or employers, depending on the program.","Set up the programs that provide social insurance benefits by using Program, Benefit Type, and Benefit records. Use Payment Request and Payment Request Line records to capture required contributions, such as a pending employer contribution for a workers’ compensation policy. Program and Benefit Management and Benefit Disbursement Settings must be enabled before users administer the associated benefits and disbursements."],connections:[{"planet":"benefit_management","desc":"Insurance policies link to benefit programs and disbursements"},{"planet":"social_programs","desc":"Social insurance programs are configured through program management"}]},
    {id:"claims-management",name:"Claims Management",icon:"\u{1F4CB}",desc:"Claims Management captures social insurance claims, claim items, and claim participants and records claim approval status and benefit eligibility. Claim records can be associated with insurance policies and the constituent accounts filing for assistance. Supporting assessment details and generated PDF files from the File a Claim flow are related to the Individual Application rather than stored as supporting documentation on the Claim record. Approved claims can proceed to a support plan, benefit assignments, and benefit disbursements.",tags:["Claim","ClaimItem","ClaimParticipant"],docs:["Use the Claim object to store claim details and record the outcome of claim review, including approval status and benefit eligibility. Claim Item records capture the items associated with a claim, while Claim Participant records relate constituents to the claim. These records support the agency’s review of the requested social insurance assistance.","For the documented workers’ compensation intake, the File a Claim flow creates both a claim and a related Individual Application. The flow stores the worker’s supplied details in assessment records and a PDF file, and relates those records and the file to the Individual Application. After a claim is approved, users can create a support plan with the Care Plan object and assign eligible benefits to the constituent; Benefit Disbursement records track delivery of those assigned benefits."],connections:[{"planet":"benefit_management","desc":"Approved claims create benefit assignments and care plans"},{"planet":"experience_cloud","desc":"Constituents file and track claims through Experience Cloud sites"}]},
    {id:"workers-compensation",name:"Workers' Compensation",icon:"\u{1F6E1}",desc:"Workers' Compensation supports social insurance for employees who become injured or ill on the job. Public Sector Solutions can capture the category of work performed by employees with Worker Compensation Coverage Class records. The File a Claim and Respond to Claim guided flows collect information from injured workers and employer representatives. Provider Management can supply healthcare provider records used during claim intake and support referrals for required care.",tags:["WorkerCompensationCoverageClass","PaymentRequest","PaymentRequestLine"],docs:["Workers’ compensation can provide replacement wages, medical treatment, and other benefits for work-related injuries or illnesses. Worker Compensation Coverage Class records represent categories of work, such as the type of work performed by an employee. Contributions to workers’ compensation programs can be mandatory and can include employer contributions recorded through payment requests.","The File a Claim flow collects the injury date and time, worksite, circumstances, nature of the injury, work capacity, employment details, and loss of income. An injured worker can also upload a certificate from a healthcare provider. Employer representatives use the Respond to Claim flow to verify submitted information, modify details with comments, and provide additional information required to process the claim."],connections:[{"planet":"provider_management","desc":"Injured workers are referred to healthcare providers for treatment"},{"planet":"experience_cloud","desc":"File a Claim and Respond to Claim flows run on Experience Cloud"}]},
    {id:"claim-guided-flows",name:"Claim Guided Flows",icon:"\u{1F9ED}",desc:"Claim Guided Flows provide Omniscript-based intake for workers’ compensation claims on a Public Sector Solutions Experience Cloud site. Injured workers use the File a Claim flow, while employer representatives use the Respond to Claim flow. The flows use Discovery Framework assessment records to retain submitted responses and generate PDF files related to Individual Applications. The Benefit Assistance template provides pages for filing, responding to, and tracking claims.",tags:["IndividualApplication"],docs:["The File a Claim flow guides an injured worker through providing injury, work capacity, employment, income-loss, and supporting certificate information. When the worker submits the flow, the CreateIndividualApplicationAndClaim Integration Procedure creates an individual application and a claim. The flow stores the supplied details in assessment records and in a PDF file, and relates the records and file to the Individual Application.","The Respond to Claim flow lets an employer representative verify the information in a filed claim, modify details, explain changes, and provide additional information. When the representative responds, the CreateIndividualApplicationForClaimResponse Integration Procedure creates an Individual Application related to the claim. The representative’s responses are stored in assessment records and a PDF file related to that Individual Application; the documented integration does not create Claim Participant records.","The Benefit Assistance template includes the Claims | File a Claim and Claims | View Claims pages. Injured workers can file claims and track their status, while employer representatives can use the Respond action from the claims list to start the response flow. Administrators deploy the Public Sector Social Insurance Discovery Framework sample template, activate the required Integration Procedures and Omniscripts, and configure the Social Insurance Claim Flow custom setting for the Respond to Claim flow."],connections:[{"planet":"experience_cloud","desc":"Guided flows are hosted on the Benefit Assistance Experience Cloud site"},{"planet":"common_features","desc":"Discovery Framework templates power the claim assessment questions"}]},
    {id:"care-barriers",name:"Care Barriers",icon:"\u{26A0}",desc:"Care Barriers identifies obstacles or circumstances that make it difficult for a constituent to obtain needed care or services. Public Sector Solutions defines categories of obstacles with Care Barrier Type and records constituent-specific obstacles with Care Barrier. Code Set and Code Set Bundle records store diagnostic codes that can be mapped to care barrier types for medical conditions. Care Plan Detail and Goal Assignment Detail connect barriers to support plans and goals.",tags:["Codeset","CodesetBundle","CareBarrier","CareBarrierType","CarePlan","CarePlanDetail"],docs:["Use Care Barrier Type to define obstacles or circumstances that impede access to care, and use Care Barrier to record the obstacle affecting a particular constituent. Code Set and Code Set Bundle records store diagnostic codes for medical conditions. Care barrier types for medical conditions can be mapped to the corresponding diagnostic codes.","Relate a constituent’s care barrier to a support plan by using Care Plan Detail. Goal Assignment Detail can relate a goal assignment to the barrier so that progress toward addressing it can be tracked. Benefit Assignment records assign eligible services or assistance, and Benefit Disbursement records track delivery; for example, an injured worker whose mobility prevents travel can receive physiotherapy sessions at home."],connections:[{"planet":"benefit_management","desc":"Care barriers inform benefit assignments and goal assignments"},{"planet":"provider_management","desc":"Care barrier resolution may involve provider referrals"}]}
  ],
  dataFlow: ["Configure social insurance policies via the Insurance Policy object, track contributions via Insurance Policy Transaction, and set up programs and benefits via Program, Benefit Type, and Benefit records.","Let constituents file and track claims through the Benefit Assistance Experience Cloud site.","Capture claim responses with Discovery Framework assessments, create the Claim and related Individual Application, and relate the generated PDF to the Individual Application.","Review the claim, claim items, participants, benefit eligibility, and approval status.","Approve eligible claims, create a support plan, and generate the required benefit assignments and benefit disbursements.","Identify care barriers and refer claimants to appropriate providers for care delivery."],
  connections: [{"planet":"benefit_management","desc":"Approved claims generate benefit assignments and disbursements"},{"planet":"social_programs","desc":"Insurance programs are managed through program and benefit settings"},{"planet":"provider_management","desc":"Claimants are referred to providers for care delivery"},{"planet":"experience_cloud","desc":"Claim filing and tracking via Benefit Assistance site"},{"planet":"common_features","desc":"Discovery Framework powers claim assessment templates"}]
},

provider_management: {
  packages: ["core"],
  name: "Provider Management",
  icon: "\u{1F3E5}",
  color: "#ec4899",
  description: "Provider Management in Public Sector Solutions supports Provider Recruitment, provider discovery, referrals, and coordinated service delivery through networks of providers, facilities, and specialties. Agencies map provider specialties to benefits, use Data Processing Engine and Criteria-Based Search and Filter to find suitable providers, and refer social program participants or insurance claimants. After authorization, providers and caseworkers coordinate schedules, sessions, enrollment, attendance, and benefit disbursements. A Service Provider Portal on Experience Cloud supports collaboration, while permission sets, Provider Management settings, and sharing settings govern provider access.",
  components: [
    {id:"provider-registry",name:"Provider Registry",icon:"\u{1F4C7}",desc:"Within this component, the documented provider-network function is Provider Recruitment. Provider Recruitment builds and manages a network by capturing details about providers, their facilities, and their specialties in the Provider Management data model. Benefit Specialty records map agency benefits to specialties offered by providers in the network, supporting later provider searches and referrals. Code Set, Code Set Bundle, and Benefit Item Code records can represent distinct services, service groupings, and benefit variations.",tags:["HealthcareProvider","HealthcareFacility","HealthcarePractitionerFacility","CareSpecialty","CareProviderFacilitySpecialty","HealthcareProviderSpecialty"],docs:["Provider Recruitment uses Healthcare Provider, Healthcare Provider Specialty, Healthcare Facility, and related objects to capture provider-network information. Public Sector Solutions can store the providers and facilities that an agency has verified, inspected, and certified against its standards. Provider Management and View Healthcare Details must be enabled before users work with the provider network and healthcare-specific details.","Agencies use Benefit Specialty to map benefits to the specialties available from providers in their network. This mapping enables caseworkers to use Provider Search to find providers and facilities that can deliver assigned benefits. Code Set records can represent distinct services and variations of a benefit, Code Set Bundle records can group code sets, and Benefit Item Code maps a benefit to a code set or Code Set Bundle."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_provider_search.htm&type=5&language=en_US",connections:[{"planet":"social_insurance","desc":"Insurance claimants are matched with qualified providers"},{"planet":"benefit_management","desc":"Provider specialties are mapped to agency benefit types"}]},
    {id:"provider-search",name:"Provider Search",icon:"\u{1F50D}",desc:"Provider Search helps caseworkers find providers and facilities that can deliver services to constituents. It uses Criteria-Based Search and Filter to define searchable criteria, result fields, grouping, sorting, distance filters, and actions for different search experiences. Data Processing Engine collates information from multiple Provider Management objects into Benefit Provider Searchable Field. Search results can expose actions such as the Provider Referral Omniscript.",tags:["BenefitPrvdSearchableFld","BenefitSpecialty","BenefitAsgntProviderLoc"],docs:["Provider Search is based on a searchable object configuration, a search criteria configuration, and optional search result action configurations. Public Sector Solutions provides the Benefit Provider Search and Provider Search with Create Referral Action configurations as starting points. Administrators can customize these configurations or create configurations based on them to support different provider types, result details, and user actions.","Provider information is distributed across multiple Provider Management objects. The Upsert Benefit Provider Searchable Field Records Data Processing Engine definition compiles that information into Benefit Provider Searchable Field, and administrators associate a cloned definition with the searchable object configuration. A schedule-triggered flow can run the definition regularly so that provider search results remain synchronized with source records.","Caseworkers can search by information such as benefit name and type, provider name and type, specialty, facility name, operating hours, and distance. Results can be grouped or sorted, and administrators can map result fields to lookup IDs so users can open the underlying records. A search result action can invoke a flow, Omniscript, or Lightning web component; the predefined Create Referral action invokes the Provider Referral Omniscript."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_provider_search.htm&type=5&language=en_US",connections:[{"planet":"benefit_management","desc":"Provider search is accessible from the Benefit Assignments related list"},{"planet":"crm_analytics","desc":"Data Processing Engine definitions power the searchable object"}]},
    {id:"provider-referrals",name:"Provider Referrals",icon:"\u{1F4E8}",desc:"Provider Referrals connect social program participants and insurance claimants with providers that can deliver required benefits or services. The Provider Referral guided flow captures the constituent, provider, source record, requested services, documents, and other referral details. It creates and shares referral records with selected network or external providers. Referral authorization lets a caseworker select a provider and grant the provider access needed to coordinate service delivery.",tags:["Referral"],docs:["Caseworkers can start the Provider Referral guided flow from provider search results, a case, or an inbound referral. The flow can include constituent and provider information, a description of required services, uploaded files, and documents from the source case, referral, or benefit assignment. It can also populate selected fillable PDF templates with constituent information and attach the completed PDFs to the created referrals.","When started from Provider Search, a caseworker can select up to three provider and facility combinations and create referrals for them. The flow creates a referral for each selected provider and relates it to the relevant constituent and source record. Providers review incoming referrals on the Service Provider Portal and request authorization for referrals that they can service.","Caseworkers use the Authorize Referral for Provider flow to update a referral's authorization status. The flow also shares the related benefit assignment and the benefit enrollee's account with the authorized provider user, enabling the provider to track delivery through benefit disbursements. Public Sector Solutions cautions against manually reassigning an authorized referral because the related shared records aren't updated for the new provider."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_provider_referral_flow.htm&type=5&language=en_US",connections:[{"planet":"social_programs","desc":"Referrals originate from case plans and benefit assignments"},{"planet":"experience_cloud","desc":"Providers process referral requests through the provider portal"}]},
    {id:"service-delivery",name:"Service Delivery",icon:"\u{2705}",desc:"Service Delivery coordinates benefit schedules, sessions, enrollment, attendance, and benefit disbursements after a referral is authorized. Providers create schedules when suitable sessions aren’t available and submit those schedules to caseworkers for approval. The approval flow creates the benefit schedule and its benefit sessions. Providers then enroll constituents and record attendance while caseworkers review delivery information on the benefit assignment.",tags:["BenefitSession","BenefitSchedule","BenefitDisbursement"],docs:["After receiving an authorized referral, a provider determines which benefit sessions the constituent requires. If sessions aren’t available, the provider creates a schedule from the Schedules page of the provider site and submits it for approval. A caseworker reviews the proposal and uses Approve & Create Sessions to approve the benefit schedule and create benefit sessions for the service occurrences.","To enroll a constituent, the provider selects the authorized benefit assignment from the Clients page and chooses one or more benefit sessions. The enrollment flow creates a benefit disbursement record for every session enrollment. This associates delivery of the assigned benefit with the scheduled session.","Providers use the Attendance page to record the constituent’s attendance for each session. Public Sector Solutions updates the related benefit disbursement records with the attendance status and disbursed quantity. Caseworkers can review attendance and disbursement quantities from the benefit assignment record."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_provider_service_delivery_workflow.htm&type=5&language=en_US",connections:[{"planet":"benefit_management","desc":"Service delivery creates benefit disbursement records"},{"planet":"experience_cloud","desc":"Providers track delivery and attendance through the provider portal"}]},
    {id:"provider-portal",name:"Provider Portal",icon:"\u{1F310}",desc:"Provider Portal is implemented with the Service Provider Portal Experience Cloud site template. It gives certified providers pages for processing referrals, managing clients and schedules, tracking attendance, and reviewing provider information. The site supports transparent collaboration by exposing authorized service-delivery records and Chatter feeds. Partner profiles, permission sets, Provider Management settings, sharing settings, and share groups control provider access.",tags:[],docs:["The Service Provider Portal template includes Home, Clients, Schedules, and Attendance experiences in addition to standard login and account pages. Providers can review and act on referrals, view authorized clients and their assigned benefits, create benefit schedules, enroll clients in sessions, and record attendance. They can also review specialties, facilities, and credentials submitted to the agency and keep that information current.","Provider users are enabled as partner users and require Omnistudio Experience Cloud User and Provider Management For Partner permissions, or the Social_Program_Management_Provider permission set group. Provider Management settings include Benefit Assignment Access, which restricts provider access to child benefit assignment records on the Experience Cloud site based on parent-record access. Organization-wide sharing defaults, share groups, or other Salesforce sharing mechanisms provide the required access to Benefit Assignment, Benefit Schedule, Benefit Session, and related records.","Chatter feed tracking can be enabled for Benefit Assignment, Benefit Schedule, Benefit Session, and Referral so record updates appear in feeds. For example, administrators can track Authorization Status on referrals and other fields needed for collaboration. Chatter must also be enabled on the provider site so provider users can view those feeds."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_service_provider_portal.htm&type=5&language=en_US",connections:[{"planet":"experience_cloud","desc":"Provider portal is built on Experience Cloud with the Service Provider Portal template"},{"planet":"setup_and_security","desc":"Partner community user profiles and permission sets control provider access"}]}
  ],
  dataFlow: ["Capture providers, facilities, credentials, and specialties through Provider Recruitment.","Map provider specialties to benefits and synchronize Benefit Provider Searchable Field with Data Processing Engine.","Search for suitable providers and refer social program participants or insurance claimants.","Review provider requests and authorize one referral for service delivery.","Approve provider schedules, create benefit sessions, and enroll the constituent.","Record attendance and benefit disbursements while enforcing portal permissions and sharing."],
  connections: [{"planet":"benefit_management","desc":"Provider specialties map to benefits and disbursements"},{"planet":"social_insurance","desc":"Insurance claimants are referred to healthcare providers"},{"planet":"social_programs","desc":"Caseworkers refer program participants to providers"},{"planet":"experience_cloud","desc":"Provider portal and referral flows on Experience Cloud"},{"planet":"setup_and_security","desc":"Permission sets control provider access and sharing"}]
},

investigative_cases: {
  packages: ["core"],
  name: "Investigative Case Management",
  icon: "\u{1F50E}",
  color: "#f97316",
  description: "Investigative Case Management in Public Sector Solutions manages investigative work from complaint intake and screening through case creation, evidence handling, legal proceedings, and resolution. Casework Overview centralizes complaints, case participants, Actionable Relationship Center graphs, Dynamic Assessments, Action Plans, Timeline activity, custody items, violations, proceedings, and interaction notes. Regulatory codes and social-program referrals support investigative decisions, Experience Cloud enables complaint intake and proceeding deferrals, and permission sets control access to investigative features. Agentforce assists with complaint intake and complaint summarization, Einstein generates notes summaries, CRM Analytics provides Caseworker Productivity Analytics dashboards, and Data 360 unifies investigative data across agencies and external sources.",
  components: [
    {id:"complaint-intake",name:"Complaint Intake",icon:"\u{1F4DD}",desc:"Complaint Intake provides guided processes for constituents, legal representatives, and complaint intake officers to report incidents and concerns. The CaseProceeding/ComplaintIntake Omniscript captures complaint information through assessment questions for regulatory codes, participants, and allegations. Submitted information creates a public complaint and related assessment question responses, while uploaded digital evidence is represented through custody item relations. Complaint intake is available through the Benefit Assistance site and can also be assisted by Agentforce AI agents.",tags:["ComplaintCase","ComplaintParticipant"],docs:["Public Sector Solutions supports complaint filing through the Benefit Assistance Experience Cloud site or through an agency complaint intake officer. The complaint form uses the CaseProceeding/ComplaintIntake Omniscript and the Public Sector Justice and Investigative Case Management Discovery Framework sample template. The CaseProceeding/RCVDetails, CaseProceeding/ParticipantDetails, and CaseProceeding/Allegations Omniscripts capture relevant regulatory codes, participant details and roles, and allegation details. When the complaint is submitted, Public Sector Solutions creates a public complaint, assessment question responses, and custody item relations for digital evidence files.","Incident managers screen complaints and conduct preliminary assessments before deciding whether further investigation is required. They can create a new case, link the complaint to an existing relevant case, or use a standard case to coordinate care plans and benefits. A single investigative case can be related to multiple complaints. In social-program scenarios, complaints can lead to assessments and referrals for services that support affected constituents.","Complaint intake requires case proceedings, evidence management, the applicable complaint-management permissions, and regulatory code configuration. Administrators deploy the Public Sector Justice and Investigative Case Management sample template and activate Complaint Intake, Allegations, ParticipantDetails, and RCVDetails Omniscripts. Experience Cloud profiles require access to the relevant Case, Public Complaint, assessment, Omnistudio, and regulatory objects. Agentforce complaint intake can answer process questions, collect required details, check whether the agency has authority, detect unresolved complaints, create the complaint, and send an acknowledgment after constituent confirmation."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_complaint_intake_judicial_investigative_cases.htm&type=5&language=en_US",connections:[{"planet":"experience_cloud","desc":"Complaint forms are hosted on the Benefit Assistance Experience Cloud site"},{"planet":"agentforce","desc":"Agentforce agents assist constituents in filing complaints"}]},
    {id:"case-investigation",name:"Case Investigation",icon:"\u{1F575}",desc:"Case Investigation centers investigative work in Casework Overview, the predefined case record page in the Investigative Case Management console app. Investigators can review complaints, participants, proceedings, violations, evidence, assessments, notes, and case activity from one interface. Actionable Relationship Center (ARC) graphs show case and participant relationships, while Timeline presents case activity chronologically. Dynamic Assessments, Action Plans, Agentforce, Einstein summaries, and unified cross-agency data can provide additional structure and context for investigative work.",tags:["CaseParticipant","CaseEpisode"],docs:["Casework Overview gives incident managers, investigators, and caseworkers a centralized view of critical case data. Its relationship views expose records related to the case, such as public complaints and case proceedings, and show relationships among case participants. Group Membership can be enabled so ARC graphs represent groups such as defense counsel, including the lawyer and defendant. The page also provides access to custody items, regulatory code violations, assessments, interaction summaries, case proceedings, case status, and Timeline.","CaseParticipant records identify accounts involved in a case and their roles and statuses. Investigators can use Interaction Summaries to capture detailed notes, next steps, attendees, files, and sharing information through a guided flow. Published interaction notes are locked against further edits and can preserve official documentation such as witness interviews. Einstein can generate notes summaries for case managers, and Agentforce AI agents can assist with complaint summarization.","Investigative activities can be organized with Action Plans and Dynamic Assessments. Dynamic Assessments based on cases can evaluate investigation steps, violation severity, and risk, while Business Rules Engine can evaluate risks and determine next steps from assessment information. Timeline can be configured around Case with related Action Plan, Assessment, Case Participant, Custody Item Relation, and Regulatory Code Violation records. Data 360 can combine investigative case and complaint information with external data, including prior cases or complaints managed by other agencies, for analysis and decision support."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_investigative_case_management_prerequisites.htm&type=5&language=en_US",connections:[{"planet":"common_features","desc":"Dynamic Assessments and Action Plans power investigation workflows"},{"planet":"einstein_ai","desc":"Einstein generates case notes summaries for investigators"}]},
    {id:"case-proceedings",name:"Case Proceedings",icon:"\u{2696}",desc:"Case Proceedings tracks criminal or civil legal proceedings that arise from investigative cases. Caseworkers can record proceeding details, add participants and roles, associate complaints, and capture regulatory code infractions. Case proceeding results document decisions and rulings, while CaseEpisode records represent events related to legal proceedings. Constituents and legal representatives can request proceeding deferrals through the Benefit Assistance site.",tags:["CaseProceeding","CaseProceedingComplaint","CaseProceedingInfraction","CaseProceedingParticipant","CaseProceedingResult"],docs:["A caseworker creates a CaseProceeding record from an investigative case and records details such as the filing date, type, description, dates, and status. Existing case participants can be added with the Add Participants quick action, or participants can be added individually with a role, status, and participation type. CaseProceedingInfraction records associate regulatory code violations with the proceeding. CaseProceedingComplaint records relate public complaints to proceedings when required by the case.","Public Sector Solutions provides a Case Proceeding Deferral service process for constituents and legal representatives on the Benefit Assistance site. The Case Proceeding Deferral Omniscript captures requested extended dates, and the Defer a Case Proceeding flow updates the proceeding dates after the request is approved. An Action Launcher deployment can expose the Request Deferral action on the CaseProceeding detail page. Agencies configure a Case-based approval process because the service process creates a case record for the deferral request.","When a proceeding concludes, a caseworker creates a CaseProceedingResult to record the decision or ruling. Results can be represented through enforcement actions, case episodes, or care plans, depending on the outcome. Case episodes specifically represent events related to legal proceedings, such as remanding a defendant to detention, suspending a driver's license, or temporarily placing a child in foster care for the duration of proceedings. They aren’t defined as general phases or milestones of an investigation."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_set_up_case_participants_addition_case_proceeding.htm&type=5&language=en_US",connections:[{"planet":"common_features","desc":"Regulatory codes and enforcement actions link to proceedings"},{"planet":"experience_cloud","desc":"Constituents can request case proceeding deferrals through the portal"}]},
    {id:"evidence-custody",name:"Evidence & Chain of Custody",icon:"\u{1F50F}",desc:"Evidence & Chain of Custody manages physical and digital evidence as custody items related to cases or case proceedings. Casework Overview includes a guided flow that captures custody item details, attachments, custodians, and related regulatory code violations in one process. CustodyItemRelation, CustodyChainEntry, and CustodyItemRgltyCodeVio records preserve the evidence relationships and possession details created from the flow. Investigators can also create and relate these records manually when evidence is entered outside the guided process.",tags:["CustodyItem","CustodyChainEntry","CustodyItemRelation","CustodyItemRgltyCodeVio"],docs:["From the Custody Items tab in Casework Overview, investigators can add a custody item, upload supporting files, enter custodian information, and select regulatory code violations already linked to the case. The flow creates a CustodyItemRelation for every item added to the case. Based on the information supplied, it also creates related CustodyChainEntry and CustodyItemRgltyCodeVio records. The custody item can then be reviewed with its files, chain entries, and regulatory code violations in Casework Overview.","When creating evidence manually, an investigator first creates the CustodyItem and then creates a CustodyItemRelation to connect it to a case or case proceeding. CustodyItemRgltyCodeVio connects the item to an applicable RegulatoryCodeViolation. CustodyChainEntry records possession details, including the custodian, custody duration, custody site, status, and verification information. Field Audit Trail is not enabled for CustodyChainEntry in the documented Public Sector Solutions list of enabled objects.","Dynamic Assessments can be based on CustodyItem to evaluate an item's relevance and whether it qualifies for a court proceeding. Discovery Framework, which underlies Dynamic Assessments, supports evaluations for evidentiary chain of custody. For large volumes of digital evidence, Amazon S3 integration lets investigators link or upload files from Salesforce records and preview or stream supported files in the browser. Permission sets determine which users can access evidence-management features and external files."],connections:[{"planet":"common_features","desc":"Custody items link to regulatory code violations"},{"planet":"setup_and_security","desc":"Evidence Management permission set controls access to custody objects"}]},
    {id:"casework-analytics",name:"Caseworker Productivity Analytics",icon:"\u{1F4CA}",desc:"Caseworker Productivity Analytics provides CRM Analytics dashboards for investigative caseloads, case trends, distribution, and processing times. Workload Management Analytics supports workload, performance, and community-impact analysis, while Case Analytics shows how long cases spend in each status and how long they take to process. The dashboards use investigative case data from Account, Case, ComplaintCase, IndividualApplication, Referral, and User records. Administrators control dashboard access through CRM Analytics permission sets and keep datasets current through scheduled synchronization and recipes.",tags:[],docs:["For Investigative Case Management, the Caseworker Productivity App includes Workload Management Analytics and Case Analytics. Workload Management Analytics presents caseloads, case trends and distribution, performance, and community impact so managers can make staffing and resource-allocation decisions. Its Summary, SLA Management, Benefits, and Leaderboard views support filtering by caseworker, time frame, ZIP code, and other criteria. Case Analytics answers how many days a case has spent in each status and how many days have been spent processing it.","Administrators enable CRM Analytics, assign CRM Analytics Plus Admin and TCRM for Public Sector Admin to analytics administrators, and assign CRM Analytics Plus User and TCRM for Public Sector User to dashboard users. Guided Setup can install the Caseworker Productivity App and add Workload Management Analytics to the supported app experience. Case Analytics can be embedded on a case record page with the CRM Analytics Dashboard component. Scheduled data synchronization and recipe runs keep analytics current."],connections:[{"planet":"crm_analytics","desc":"Caseworker Productivity dashboards are built on CRM Analytics"},{"planet":"setup_and_security","desc":"Analytics access requires CRM Analytics enablement and permissions"}]},
    {id:"complaint-assessments",name:"Complaint Assessments",icon:"\u{1F4CB}",desc:"Complaint Assessments use Dynamic Assessments to evaluate allegations, complaint severity, and the need for additional investigation. Case managers define assessment questions, organize them into Omni Assessment Tasks, and include those tasks in Action Plan Templates for repeatable evaluations. Incident managers complete preliminary complaint assessments, while investigators can use related case and risk assessments during formal investigations. Business Rules Engine can evaluate assessment information to support risk evaluation and next-step decisions.",tags:[],docs:["Dynamic Assessments are built on Discovery Framework and collect responses through Omniscript forms. For investigative scenarios, assessment questions can be related to RegulatoryCode and ViolationType records so users can view applicable codes and record observed violations. An Omni Assessment Task stores the questions and the Omniscript conditional logic that sequences them. Action Plan Templates group these tasks into checklists for preliminary complaint evaluation, case assessment, or risk assessment.","For preliminary complaint assessments, the action plan template uses PublicComplaint as its target object. For case and risk evaluations, the template uses Case as its target object. A case manager creates an action plan from the relevant template, and incident managers, investigators, or caseworkers complete the assessment tasks and responses. Business Rules Engine can evaluate risks and determine next steps from information gathered during the Dynamic Assessment.","Setup requires Discovery Framework, Dynamic Assessment Access, Industries Assessment, Action Plans, and the appropriate Omnistudio permissions. Assessments involving regulatory compliance also require Public Sector Access, while onsite assessments require Industries Visit. The Assessment List and Action Plan List components expose tasks and action plans on supported record pages. Permission sets and permission set groups control which administrators and investigative users can configure or conduct assessments."],connections:[{"planet":"common_features","desc":"Discovery Framework and Dynamic Assessments power evaluation workflows"},{"planet":"agentforce","desc":"Agentforce assists complaint management officers with AI-powered summaries"}]}
  ],
  dataFlow: ["File the complaint through the Benefit Assistance site, a complaint intake officer, or an Agentforce-assisted intake conversation.","Assess the allegations with Dynamic Assessments, link the complaint to an existing case or create a case, and initiate applicable program referrals.","Investigate the case in Casework Overview by reviewing ARC relationships, participants, Timeline activity, notes, violations, and unified cross-agency data.","Collect evidence as custody items, record custody chain entries, and relate applicable regulatory code violations.","Initiate the case proceeding, process any deferral request, and add participants, complaints, and infractions.","Record proceeding results and legal-event case episodes, then monitor caseloads and processing times in Caseworker Productivity Analytics."],
  connections: [{"planet":"common_features","desc":"Regulatory codes, Dynamic Assessments, and Action Plans support investigations"},{"planet":"experience_cloud","desc":"Complaint intake and proceeding deferrals via Benefit Assistance site"},{"planet":"agentforce","desc":"AI agents assist with complaint intake and case summarization"},{"planet":"einstein_ai","desc":"Einstein generates notes summaries for case managers"},{"planet":"crm_analytics","desc":"Caseworker Productivity Analytics dashboards"},{"planet":"setup_and_security","desc":"Permission sets control access to investigation features"},{"planet":"social_programs","desc":"Complaints trigger program referrals and assessments"},{"planet":"data_360","desc":"Cross-agency case data unification"}]
},

talent_recruitment: {
  packages: ["core"],
  name: "Talent Recruitment Management",
  icon: "\u{1F4BC}",
  color: "#a855f7",
  description: "Talent Recruitment Management in Public Sector Solutions supports the hiring lifecycle from occupation and position classification through requisitions, postings, applications, Dynamic Assessments, vetting, employment offers, and employee record creation. It provides a console app for recruiters and HR specialists, an Experience Cloud career site for applicants, and an employee site for hiring managers and interviewers. Criteria-Based Search and Filter, OmniStudio guided flows, and Compliant Data Sharing support search, intake, collaboration, and controlled access, while Agentforce agents assist with candidate sourcing and application screening. Accepted offers can progress to employee onboarding, and applicant and employee data can be unified in Data 360 for analytics.",
  components: [
    {id:"position-classification",name:"Position Classification",icon:"\u{1F3DB}",desc:"Position Classification structures workforce requirements by organizing related occupations, defining functional positions, and creating specific job positions for employees or vacancies. HR staff can associate positions and job positions with pay grades, steps, location adjustments, competencies, and qualifications. These classifications provide the foundation for requisitions, candidate matching, employment offers, and employee records in Public Sector Solutions.",tags:["JobPosition","JobPositionPayGrade","Position","PositionPayGrade","PayGrade","PayGradeStep","PayGradeStepLocation","Occupation","OccupationGroup"],docs:["Occupation groups represent broad categories of related work, while occupations represent specialized categories requiring similar skills, knowledge, or qualifications. A position defines a functional role within an occupation, including its duties, schedule, sensitivity, status, and qualification requirements. A job position is a specific instance of a position in the organization and can identify the department, assigned employee, status, and start date.","Pay grades define salary ranges for positions with comparable responsibilities and competency requirements. Pay grade steps represent increases within a grade, and pay grade step locations capture location-specific adjustments. Position Pay Grade and Job Position Pay Grade records associate the applicable compensation structures with positions and individual job positions.","Administrators can use Data Loader to import occupation groups, occupations, positions, competencies, qualifications, and related classification data in bulk. HR teams should review the Public Sector Solutions Talent Recruitment Management data model and add custom fields only when additional organizational information is required. Position competency and qualification requirements help recruiters identify qualified applicants and support compliance with hiring requirements."],connections:[{"planet":"employee_experience","desc":"Position classifications define employee roles and compensation"},{"planet":"data_360","desc":"Position and pay data integrates with Data 360 for workforce analytics"}]},
    {id:"requisition-management",name:"Requisition Management",icon:"\u{1F4C4}",desc:"Requisition Management supports formal requests to fill specific job positions and collaboration between recruiters and hiring managers. Recruiters create requisitions, relate them to vacant job positions, add hiring managers as participants, and submit the records for approval. Public Sector Solutions can use approval processes and Compliant Data Sharing to control review workflows and access to requisition records.",tags:["RecruitmentRequisition","RecruitmentRequisitionLoc","RecruitmentRequisitionPtcp","JobPstnRecruitmentRqs"],docs:["A recruiter creates a Recruitment Requisition with internal and external vacancy titles, a description, an expected hiring date, and an initial state such as Draft. A Job Position Recruitment Requisition record associates the requisition with the vacant job position for an effective period. Recruitment Requisition Location records can capture applicable locations, while Recruitment Requisition Participant records identify participating users and their roles.","Before requesting approval, the recruiter adds the hiring manager as a participant and selects the appropriate Compliant Data Sharing participant role. The approval process can route the requisition to the hiring manager on the employee site and update Approval Status and State based on approval or rejection. An approved requisition is then available for the recruiter to use when creating recruitment postings.","Public Sector Solutions supports Compliant Data Sharing for Recruitment Requisition records when the organization-wide sharing default is Private or Public Read-Only. Participant roles can provide HR specialists with read/write access and hiring managers with the access required to review and manage requisitions. This approach extends record access to designated participants without making all requisitions publicly writable."],connections:[{"planet":"setup_and_security","desc":"Approval processes control requisition review workflows"},{"planet":"experience_cloud","desc":"Hiring managers review requisitions on the employee site"}]},
    {id:"job-postings",name:"Job Postings",icon:"\u{1F4E2}",desc:"Job Postings turn approved recruitment requisitions into internal or external opportunities that job seekers can review. Recruiters use the Create Recruitment Posting guided flow to define posting details and assemble Overview, Summary, and Duties content sections. After approval, posting data is consolidated by Data Processing Engine so the opportunity can appear in search results on the career site.",tags:["RecruitmentPosting","RecruitmentPostingCntntSect","RecruitmentContentSection"],docs:["A recruiter creates a job posting for an approved recruitment requisition by starting the Create Recruitment Posting guided flow from the Recruitment Postings related list. The recruiter selects the Candidate Source Key, posting type, status, effective dates, and target portal. The flow obtains the external vacancy title and requisition ID from the related requisition.","Each posting can contain Overview, Summary, and Duties sections. Recruiters can create new Recruitment Content Section records, reuse existing sections, or start from existing content and revise it. Recruitment Posting Content Section records associate those sections with the Recruitment Posting, and the guided flow provides a preview before the recruiter saves the posting.","Recruitment postings can follow an approval process in which the hiring manager approves or rejects a draft posting from the employee site. Approval can update the posting Status to Active, but it does not itself create the posting or immediately publish it. Data Processing Engine consolidates posting information from Recruitment Requisition, Recruitment Posting, Position, Job Position, and related objects into Job Posting Searchable Field, and an approved posting goes live after the next scheduled Data Processing Engine job run."],connections:[{"planet":"experience_cloud","desc":"Job postings are published on the career site for applicants"},{"planet":"agentforce","desc":"Agentforce recommends matching job postings to applicants"}]},
    {id:"applicant-evaluation",name:"Applicant Evaluation",icon:"\u{1F9D1}",desc:"Applicant Evaluation helps recruiters screen applications and coordinate structured reviews by hiring managers and interviewers. Application information can be summarized for initial screening, while Dynamic Assessments provide repeatable questions and tasks for interviews, panel reviews, and other evaluations. Evaluation decisions and assessment responses give recruiters and hiring managers a consistent basis for hiring decisions.",tags:["ApplicationFormRelation","ApplicationFormEvalPtcp"],docs:["Applicants submit job applications through a guided flow on the career site, and Public Sector Solutions stores the application in an Application Form related to the applicable Recruitment Requisition through Application Form Relation. Applicant information can span person accounts, party profiles, education, employment, competency, and document checklist records. The application summary and application review panes consolidate this information so recruiters, hiring managers, interviewers, and applicants can review relevant details without navigating each source object separately.","Recruiters use Criteria-Based Search and Filter to find applications associated with a requisition and narrow results by application stage, employment offer status, evaluation decision, candidate source, qualification, location, job position, or applicant details. After reviewing an application and its supporting documents, the recruiter can move a qualifying application to the Screened stage. Agentforce agents can also assist by summarizing application forms and sharing shortlisted applications with hiring managers, while recruiters remain responsible for screening and hiring decisions.","For applicants who advance, recruiters create Application Form Evaluation records for hiring managers and interviewers. They add action plans based on assessment templates, creating Dynamic Assessment tasks that evaluators complete on the employee site or in the Talent Recruitment Management app. Application Form Participants and Application Form Evaluation Participants associate users with the application and evaluations and support participant-role-based access through Compliant Data Sharing."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_recruitment_multi_section_applications.htm&type=5&language=en_US",connections:[{"planet":"common_features","desc":"Dynamic Assessments power applicant evaluation questionnaires"},{"planet":"agentforce","desc":"Agentforce summarizes applications and assists with screening"}]},
    {id:"vetting-evaluations",name:"Vetting Evaluations",icon:"\u{1F50D}",desc:"Vetting Evaluations support checks that determine whether a selected applicant meets suitability, fit, and eligibility requirements. Recruiters create separate evaluation records and assessment action plans for procedures such as background checks, health examinations, and reference checks. The recorded outcomes inform whether a tentative employment offer can be finalized or must be revoked.",tags:["VettingEvaluation","Examination","PersonExamination","CourseOffering"],docs:["After an applicant accepts a tentative offer, the recruiter creates a Vetting Evaluation for the applicant and associates it with the relevant application form and a reference record such as a recruitment requisition, position, or job position. The recruiter then creates an action plan from the template for the applicable vetting procedure. Employment Offer Vetting Evaluation records relate each vetting evaluation to the associated employment offer.","Public Sector Solutions uses Dynamic Assessments to administer vetting requirements, with assessment questions organized into Omni Assessment Tasks and action plan templates. Recruiters work with applicants and vetting agencies to complete the assessment tasks and can upload supporting reports or documents to the Vetting Evaluation record. After reviewing assessment responses, the recruiter records the evaluation Outcome and uses the combined results to determine whether the applicant cleared vetting."],connections:[{"planet":"setup_and_security","desc":"Vetting requires specialized permission sets and security controls"},{"planet":"agentforce","desc":"Skill-Based Candidate Sourcing uses examination and competency data"}]},
    {id:"employment-offers",name:"Employment Offers",icon:"\u{1F4E9}",desc:"Employment Offers manage tentative and final offers for applicants selected by the hiring team. HR specialists record the recipient, job position, manager, compensation, offer dates, status, and related application form. Vetting outcomes determine whether a tentative offer is converted to a final offer or revoked.",tags:["EmploymentOffer","EmploymentOfferVettingEval"],docs:["For an applicant approved by the hiring team, an HR specialist creates an Employment Offer with Type set to Tentative. The record can identify the recipient, manager, job position, related application form, pay grade, offered pay, offer date, expiration date, and Status. The HR specialist shares the offer with the applicant and requests a response before the expiration date.","After the applicant accepts the tentative offer, Employment Offer Vetting Evaluation records connect the offer with the required vetting evaluations. If the applicant clears those evaluations, the HR specialist changes the offer Type to Final, requests the applicant’s response, and updates the Status accordingly. If the applicant fails vetting, the specialist revokes the offer, records the reason, and closes the related application.","When a selected applicant accepts the final offer, an HR specialist can start onboarding by creating an employee record. The Create Employee screen flow creates the Employee record and related person account and contact records. The specialist can then create an Employment record to capture details such as the effective date, employment type, status, and schedule type."],connections:[{"planet":"employee_experience","desc":"Accepted offers lead to employee record creation and onboarding"},{"planet":"experience_cloud","desc":"Applicants view employment offers on the career site"}]},
    {id:"recruitment-search",name:"Recruitment Search",icon:"\u{1F50E}",desc:"Recruitment Search provides distinct Criteria-Based Search and Filter experiences for recruiters and job seekers. Recruiters search Job Application Searchable Field for applications that meet hiring criteria, while job seekers search Job Posting Searchable Field for opportunities matching their preferences. Scheduled Data Processing Engine definitions keep both searchable objects synchronized with recruitment data stored across multiple objects.",tags:[],docs:["Criteria-Based Search and Filter aggregates information from multiple fields and objects into a searchable object. Public Sector Solutions provides sample searchable object configurations and search configurations for Job Application Search and Job Posting Search. Administrators can customize the searchable fields, result fields, grouping, sorting, filtering, and result display for each experience.","For recruiter search, the Aggregate Job Application Details for Search Data Processing Engine definition consolidates application, applicant, education, employment, evaluation, offer, and related requisition data into Job Application Searchable Field. Recruiters start the configured experience from the Search action on the Application Form Relations related list of a Recruitment Requisition. They can search by requisition, posting, application stage, offer status, evaluation decision, candidate source, or qualification and further filter the results by location, job position, application, applicant name, or email.","For job seeker search, the Aggregate Job Posting Details for Search Data Processing Engine definition consolidates information from Recruitment Posting, Recruitment Requisition, Position, Job Position, Occupation, pay grade, and related records into Job Posting Searchable Field. The career site exposes the Job Posting Search configuration through the Criteria-Based Search and Filter component. Job seekers can search by position title, location, occupation group, occupation, pay range, schedule, or position type and open a result to review and apply for the job.","Administrators clone and activate the provided Data Processing Engine definition templates, associate them with the corresponding searchable object configurations, and create schedule-triggered flows to run them regularly. The scheduled runs create, update, or delete searchable records as source recruitment data changes. This synchronization is also what makes an approved, Active posting available on the career site after the next scheduled job run."],connections:[{"planet":"experience_cloud","desc":"Job posting search is available on the career site home page"},{"planet":"common_features","desc":"Criteria-Based Search and Filter framework powers all recruitment search"}]}
  ],
  dataFlow: ["Classify occupations and positions, assign pay grades and qualifications, and create the required job positions.","Create recruitment requisitions, add hiring managers as participants, and route the records for approval through the employee site with Compliant Data Sharing.","Create job postings for approved requisitions, obtain hiring-manager approval, and run Data Processing Engine to publish searchable opportunities on the career site.","Collect guided applications, use Criteria-Based Search and Filter to find matches, and use Agentforce agents to assist with candidate sourcing and application screening.","Create Dynamic Assessment tasks for applicant evaluations and vetting procedures, then record evaluator decisions and vetting outcomes.","Issue tentative and final employment offers, create employee and employment records for accepted offers, and unify applicant and employee data in Data 360 for analytics and onboarding processes."],
  connections: [{"planet":"experience_cloud","desc":"Career site for applicants and employee site for hiring managers"},{"planet":"agentforce","desc":"AI agents assist with candidate sourcing and application screening"},{"planet":"common_features","desc":"Dynamic Assessments and Criteria-Based Search power recruitment"},{"planet":"employee_experience","desc":"Accepted offers lead to employee onboarding"},{"planet":"setup_and_security","desc":"Compliant data sharing controls access to recruitment records"},{"planet":"data_360","desc":"Applicant and employee data unifies in Data 360 for analytics"}]
},

agentforce: {
  packages: ["core"],
  name: "Agentforce",
  icon: "\u{1F916}",
  color: "#6366f1",
  description: "Public Sector Solutions provides Agentforce agents for Talent Recruitment Management and Investigative Case Management, covering candidate sourcing, job recommendations, recruitment FAQs, complaint intake, complaint resolution, and complaint-to-case conversion. Constituent-facing agents are deployed on Experience Cloud sites, while employee agents use documented Agentforce actions, Einstein generative AI, Einstein Search Retrievers, prompt templates, flows, Data 360, Business Rules Engine, Discovery Framework, and Omnistudio components. Recruitment agents identify candidates, create outreach leads, and recommend jobs, while complaint agents create PublicComplaint records or create and link investigative Case records and related investigative data. Permission sets and agent-access assignments control access; related Public Sector Solutions deployments include Constituent Agent for LPI Assistance for license, permit, and inspection needs, inspection scheduling and status topics, and Agentforce IT Service for employee self-service.",
  components: [
    {id:"candidate-sourcing-agent",name:"Candidate Sourcing Agent",icon:"\u{1F50D}",desc:"The Candidate Sourcing Agent helps recruiters identify potential candidates for a job opening from past applicants or by matching specified skills and job specializations. It can review relevant Application Form records, PersonCompetency records, and Person Examination records, then create Lead records for selected candidates. Recruiters can use those leads to track outreach and send template-based emails that invite candidates to apply. The agent supports Talent Recruitment Management workflows without replacing the recruiter’s responsibility to review and evaluate candidates.",tags:["ApplicationForm","ApplicationFormRelation","Lead","PartyProfile","PersonCompetency","PersonExamination"],docs:["Public Sector Solutions provides the Candidate Sourcing and Skill-Based Candidate Sourcing subagents for recruiter workflows. Candidate Sourcing finds past Application Form records associated with Recruitment Requisition records that have the same vacancy title and can filter the results by recruitment stage. Skill-Based Candidate Sourcing uses competencies and examinations associated with applicants and job requirements to find candidates whose skills align with a Recruitment Posting or a recruiter’s request. Recruiters remain responsible for reviewing the results and identifying the best candidates for a role.","After a recruiter selects potential candidates, the agent can create Lead records using information from the applicants’ Account and PartyProfile records and the relevant Recruitment Posting. The leads identify the applicants as potential candidates and provide records for tracking outreach. The Email Candidate Leads flow sends template-based outreach messages to candidate leads that haven’t yet been contacted and then updates the leads to record the outreach. The outreach template can include a link to the Public Sector Solutions career site.","Set up the agent from the Agentforce Employee Agent template and add either the Candidate Sourcing or Skill-Based Candidate Sourcing subagent, depending on the sourcing approach. Skill-based sourcing requires applicant profile and job data, an Einstein Search Retriever for Competency and Examination, an ensemble retriever, the Fetch Examination and Competency prompt template, and supporting flows. Recruiters require Talent Recruitment Management Specialist Access and an assigned permission set that grants access to the agent. Test the agent in Agentforce Builder before activation and verify its recommendations before making hiring decisions."],connections:[{"planet":"talent_recruitment","desc":"Sources candidates from recruitment requisitions and past applications"},{"planet":"experience_cloud","desc":"Outreach emails link candidates to the career site"}]},
    {id:"job-recommendation-agent",name:"Job Recommendation Agent",icon:"\u{2B50}",desc:"The Job Recommendation Agent helps applicants find relevant job openings through the Public Sector Solutions Applicant Portal. It uses applicant profile information, preferred locations, or specified distance criteria to retrieve matching Recruitment Posting records. The agent combines Agentforce, Einstein Search and RAG, applicant profile data, and standard flows and actions. Recommendations are presented through a conversational interface on an Experience Cloud site.",tags:["RecruitmentPosting","PartyProfileAddress","PersonEducation","PersonEmployment"],docs:["The Job Recommendation Agent uses applicant information stored in PartyProfile, PartyProfileAddress, PersonEducation, PersonEmployment, and PersonCompetency records to tailor recommendations. Accurate and current profile data is important because the agent uses it to identify suitable job openings and location preferences. The Find Matching Recruitment Postings prompt template uses a configured Einstein Search Retriever to search Recruitment Posting records. The retriever’s search index must include the required fields, including Id and Posting Keywords.","The Job Recommendation subagent includes actions for finding matching postings, getting recommended positions, retrieving the user’s current city, filtering matching job locations, and formatting postings as cards. Get User's Current City reads the applicant’s current location from a PartyProfileAddress record whose type is Current. Get Matching Job Locations applies user-supplied location or distance criteria, while Format Postings as Cards prepares titles, locations, skill matches, and links for display in the chat interface. The Get Recommended Job Positions flow orchestrates these operations and uses the configured base URL for Recruitment Posting pages on the Applicant Portal.","Create the agent from the Agentforce Employee Agent template, add the Job Recommendation subagent, and activate it after reviewing its actions. Applicants require the documented applicant, flow, community, and agent-access permissions. Deploy the agent through an Omni-Channel flow and an Embedded Messaging component on the Experience Cloud site, with credential-based user verification enabled so the agent can identify the logged-in applicant. Test the deployed agent with an authenticated applicant and allow time for retriever indexing before evaluating recommendation quality."],connections:[{"planet":"talent_recruitment","desc":"Recommends matching recruitment postings to applicants"},{"planet":"experience_cloud","desc":"Deployed as Embedded Messaging on the Applicant Portal"}]},
    {id:"recruitment-faq-agent",name:"Recruitment FAQ Agent",icon:"\u{2753}",desc:"The Recruitment FAQ Agent gives job seekers conversational answers about an agency’s hiring process, culture, mission, and work policies. It grounds answers in approved recruitment documents stored in the Agentforce Data Library and provides source citations. The agent is designed for unauthenticated guest users on a Public Sector Solutions career portal. It doesn’t provide personalized job recommendations or application status updates.",tags:[],docs:["Public Sector Solutions provides the Recruitment FAQ subagent for an Agentforce Service Agent. Its Answer General Company Questions action uses Data Cloud retrieval augmented generation to answer questions from recruitment FAQ documents, mission statements, policy manuals, and other approved content in the Agentforce Data Library. Responses include source citations that identify the document and section used to ground the answer. The agent’s scope is limited to information available in the uploaded documents.","Before deployment, enable Einstein Generative AI for Public Sector and create an Agentforce Data Library that uses Files as its data type. Upload the agency’s recruitment documents and wait until indexing is complete before testing responses. Documents shouldn’t contain personally identifiable information or sensitive unreleased data. The agent’s welcome message must notify users that they’re interacting with AI and that generated output can require verification.","Create the agent from the Agentforce Service Agent template and add the Recruitment FAQ subagent. Assign the required permission set license to the Digital Agent user because the agent runs in that user’s context. Add Embedded Messaging to the Public Sector Solutions career portal and route conversations to the agent through an inbound Omni-Channel flow. This guest-facing deployment answers generic recruitment questions but leaves authenticated, personalized functions to the appropriate applicant agents."],connections:[{"planet":"talent_recruitment","desc":"Assists applicants with recruitment-related questions"},{"planet":"experience_cloud","desc":"Available to guest users on the career portal"}]},
    {id:"complaint-intake-agent",name:"Complaint Intake Agent",icon:"\u{1F4AC}",desc:"The Complaint Intake Agent helps constituents file routine public complaints through a Public Sector Solutions self-service site. It answers intake questions, checks whether the agency has authority to handle an issue, gathers missing details, detects potentially duplicate unresolved complaints, and previews the complaint before submission. After confirmation, it creates a PublicComplaint record and sends an acknowledgment email. Sensitive or emergency matters must be redirected to appropriate channels or escalated to a service representative.",tags:["PublicComplaint"],docs:["The agent is built with the Agentforce Service Agent template and the prebuilt Complaint Intake subagent. It can use agency policy documents to answer questions about intake procedures and determine whether the agency has authority to receive, review, and resolve the complaint. If the agency lacks authority, the agent informs the constituent and can provide guidance about the appropriate next step. The Answer Questions from Document and Check Complaint Authority actions are grounded in documents from an Agentforce Data Library.","During intake, the agent extracts key details from the conversation and prompts the constituent for missing information. Summarize Complaint for Constituent uses generative AI to present the details for review, and the constituent can request corrections in the chat. Get Constituent’s Unresolved Complaints checks for pending complaints about the same matter before a new record is created. After final confirmation, Create Complaint creates the PublicComplaint record and Email Complaint Acknowledgment sends a generated confirmation email based on the complaint information.","This agent is intended for routine complaints and isn’t intended for emergencies or sensitive matters involving violence, abuse, self-harm, harassment, or illegal activity. Configure the Inappropriate_Content subagent to deny processing of such complaints and invoke the Escalation subagent for transfer to a human representative. Review the Type and Subtype picklist values on PublicComplaint and align the Complaint Intake subagent instructions with the categories used by the agency. Deploy the agent through Embedded Messaging on an Experience Cloud site after assigning the documented permissions to the agent user and testing the authority, duplicate-checking, creation, email, and escalation paths."],connections:[{"planet":"investigative_cases","desc":"Creates complaint records that feed into investigative case management"},{"planet":"experience_cloud","desc":"Deployed on the Benefit Assistance self-service site"}]},
    {id:"complaint-management-agent",name:"Complaint Management Agent",icon:"\u{1F4C3}",desc:"The Complaint Management Agent helps complaint intake officers prioritize, investigate, and resolve PublicComplaint records. Its Complaint Resolution capabilities summarize complaints, find similar complaints, identify possible regulatory code breaches, administer assessments, create regulatory code violations, and notify participants. Its Complaint-to-Case Conversion capabilities create a Case from a PublicComplaint or link the complaint to an existing Case. It can also transfer relevant complaint participants, custody items, and regulatory code violations to the linked Case.",tags:[],docs:["The Complaint Resolution subagent supports review and resolution strategy. It can create a rich-text complaint summary, find similar resolved or unresolved complaints, identify complaints involving common perpetrators, and retrieve relevant Regulatory Code records. Supporting actions can create Regulatory Code Violation records, administer Discovery Framework assessments, capture Assessment Question Response records, and email complainants or perpetrators. Public Sector Solutions can also calculate a complaint’s Resolution Priority by using flows, decision matrices, and the Calculate Public Complaint Score expression set.","The Complaint-to-Case Conversion subagent keeps complaint and investigative-case operations distinct from recruitment operations. It can find open Case records with similar descriptions or common perpetrators, create a Case from a PublicComplaint, or create a ComplaintCase record that links the complaint to an existing Case. Additional actions copy relevant ComplaintParticipant information into CaseParticipant records and create related CustodyItemRelation and Regulatory Code Violation records for the Case. These actions support investigative case creation and management; they don’t create or update recruitment records.","Complaint Management uses Data 360 data streams, hybrid search indexes, and retrievers for PublicComplaint, Case, and RegulatoryCode data where documented. Prompt templates use those retrievers to find similar complaints, similar cases, and relevant regulatory codes, while Business Rules Engine supports complaint-priority calculations. Discovery Framework supplies assessment questions and responses for complaint-review procedures. Source records, retrievers, prompt templates, flows, decision matrices, and expression sets must be configured and activated before the agent is used.","Create the agent from the Agentforce Employee Agent template and add the Complaint Resolution and Complaint-to-Case Conversion subagents. Complaint intake officers require the Investigative_Case_Management_Officer permission set group, Agentforce for Public Sector, Data Cloud User, Prompt Template User, flow access, and a permission set that grants access to the agent. Access to underlying records remains subject to object permissions, field permissions, sharing, and the assigned agent-access permission set. Test the subagents in Agentforce Builder before activation and have officers review agent output before making investigative decisions."],connections:[{"planet":"investigative_cases","desc":"Supports intake officers in screening and assessing complaints"},{"planet":"einstein_ai","desc":"Leverages Einstein generative AI for complaint summarization"}]}
  ],
  dataFlow: ["Deploy constituent agents through Embedded Messaging on Public Sector Solutions Experience Cloud sites, and grant employee agents through assigned agent-access permission sets.","Collect applicant profile, education, competency, location, and past application data for candidate sourcing and job recommendations, while handling recruitment FAQ interactions separately for unauthenticated guest users without personal-data access.","Identify recruitment candidates, create Lead records for selected applicants, send outreach emails, or return matching Recruitment Posting records to job seekers.","Gather and confirm complaint details, check agency authority and unresolved complaints, and create a PublicComplaint record after constituent approval.","Prioritize and review PublicComplaint records with Business Rules Engine, Data 360 retrievers, prompt templates, flows, and Discovery Framework assessments where configured.","Create a Case from a PublicComplaint or link it to an existing Case, then transfer relevant participants, custody items, and regulatory code violations for investigation."],
  connections: [{"planet":"talent_recruitment","desc":"Candidate sourcing and job recommendation agents support recruitment"},{"planet":"investigative_cases","desc":"Complaint intake and management agents support investigations"},{"planet":"experience_cloud","desc":"Agents are deployed on Experience Cloud portals"},{"planet":"einstein_ai","desc":"Agents use Einstein generative AI for summaries and content generation"},{"planet":"setup_and_security","desc":"Agent access is controlled through permission sets"},{"planet":"common_features","desc":"Agent actions leverage Business Rules Engine and OmniStudio"},{"planet":"licensing_and_permitting","desc":"Application Assistance agent for permit inquiries"},{"planet":"inspections","desc":"Inspection scheduling and status agent topics"},{"planet":"employee_experience","desc":"IT Service agent for employee self-service"}]
},

einstein_ai: {
  packages: ["core"],
  name: "Einstein Generative AI",
  icon: "\u{1F9E0}",
  color: "#2563eb",
  description: "Einstein Generative AI in Public Sector Solutions provides AI-generated summaries, comparisons, and drafted content for benefit management, licensing and permitting, inspections, investigative cases, grantmaking, and social program management. Built-in prompt templates and template-triggered flows ground responses in Salesforce records, while Data 360 can supply integrated grounding data for AI models. Users generate and review responses through the Einstein Summary component, with record-field saving available only for Field Generation prompt templates. These capabilities require the applicable add-on licenses and permission sets, and Agentforce agents can leverage Einstein AI capabilities in supported workflows.",
  components: [
    {id:"benefit-ai-features",name:"Benefit Management AI",icon:"\u{1F4C8}",desc:"Benefit Management AI uses built-in prompt templates and template-triggered flows to summarize benefit applications and household information in Public Sector Solutions. Application History Overview highlights key dates, application status, eligibility determinations, recertification details, and associated assessments. Application Version Comparison identifies changes across benefit application assessments, while Household Overview summarizes household members, income, relationships, benefits, and program participation. Users access these capabilities through the Einstein Summary component on the relevant Individual Application or Person Account record page.",tags:["IndividualApplication","Assessment","BenefitAssignment","BenefitDisbursement"],docs:["Application History Overview uses the Create Application History Overview prompt template and the Get Benefit Application Details template-triggered flow. Its grounding sources are Assessment, Benefit Assignment, Benefit Disbursement, and Individual Application. The generated overview helps caseworkers understand submission, evaluation, eligibility, and recertification history without navigating multiple related records. Because this feature uses a Field Generation prompt template, users can copy or edit the response and save it to the Application Overview field.","Application Version Comparison uses the Compare Application Versions prompt template and the Get Assessment Differences for Individual Application template-triggered flow. It compares responses from two or more assessments associated with a revised benefit application. Its grounding sources are Individual Application, Assessment, Assessment Question, and Assessment Question Response. As a Field Generation feature, the comparison can be copied or edited and saved to the Application Change Overview field.","Household Overview uses the Create Household Overview prompt template and the Get Household Details template-triggered flow on a Person Account record page. It is grounded in Benefit Assignment, Benefit, Contact, Contact Contact Relationship, Account Contact Relationship, Party Income, Person Account, Program, and Program Enrollment data. The response summarizes household members, ages, incomes, relationships, benefits, and program participation to support benefit eligibility decisions. The Unified Constituent Profile for Benefit Management can combine Einstein-generated summaries with priority alerts and Data 360 insights on a single account page."],connections:[{"planet":"benefit_management","desc":"AI features summarize benefit applications and household data"},{"planet":"social_programs","desc":"Program enrollment data grounds the household overview"}]},
    {id:"compliance-ai-features",name:"Compliance & Inspection AI",icon:"\u{1F50D}",desc:"Compliance & Inspection AI provides License Compliance Summary and Prior Violation Report capabilities in Public Sector Solutions. License Compliance Summary identifies license and permit status, missing authorizations, outstanding regulatory code violations, and regulatory fees for a business. Prior Violation Report summarizes violations from previous visits, repeated occurrences, and related enforcement action status. These insights help compliance officers and inspectors plan renewals, follow-up work, and inspection focus areas.",tags:["BusinessLicense","RegulatoryCodeViolation","Visit"],docs:["License Compliance Summary uses the Summarize License Compliance prompt template and the Get License Information template-triggered flow on an Account record page. Its grounding sources are Business License, Business Regulatory Authorization Type, Business Type, Regulatory Code Violation, Regulatory Fee, Regulatory Fee Item, and Regulatory Authorization Type. The summary can identify expired licenses, licenses nearing expiration, authorizations pending verification, required licenses or permits that have not been applied for, outstanding violations, and outstanding fees. It is configured as a Record Summary prompt template in the Einstein Summary component.","Prior Violation Report uses the Compile Prior Violations prompt template and the Get Visit Inspection History template-triggered flow on a Visit record page. Its grounding sources are Regulatory Code, Regulatory Code Violation, Violation Enforcement Action, and Visit. The generated report identifies previously violated codes, repeated violations, and enforcement action status so users can determine the scope and priorities of a follow-up visit. Because it uses a Field Generation prompt template, users can copy or edit the response and save it to the Inspection Overview field.","Administrators add the Einstein Summary component to the applicable Account and Visit record pages and select the corresponding prompt template type and template. Users acknowledge the AI disclaimer before generating a response and can copy or edit the output. Public Sector Solutions applies the running user’s roles, permissions, and field-level security when prompt templates access grounding data. The Einstein Trust Layer can mask sensitive data and applies controls intended to reduce hallucinations and toxicity."],connections:[{"planet":"licensing_and_permitting","desc":"License compliance summaries analyze permit and license data"},{"planet":"inspections","desc":"Prior violation reports summarize inspection visit histories"}]},
    {id:"grantmaking-ai-features",name:"Grantmaking AI",icon:"\u{1F4B0}",desc:"Grantmaking AI uses Einstein generative AI in Public Sector Solutions to create a Board Version of Grant Application and a Funding Award Summary. The board version distills grant application information for board review and final approval. The funding award summary helps program officers assess grant health, milestones, requirements, performance, and disbursement information. Both capabilities are Record Summary features and are limited to 100 related records used as grounding data.",tags:["FundingAward","FundingOpportunity","FundingDisbursement"],docs:["Board Version of Grant Application uses the Create Board Version Application prompt template on an Individual Application record page. Its grounding sources are Application Review, Funding Opportunity, and Individual Application. Grantmaking program officers can generate a distilled version of an application for board members without manually assembling the summary. Users can copy the response into another document or select Generate to produce another version.","Funding Award Summary uses the Summarize Funding Award prompt template on a Funding Award record page. Its grounding sources are Funding Award, Funding Award Requirement, Funding Disbursement, Funding Opportunity, Indicator Performance Period, and Indicator Results. The generated content helps program officers determine whether a grant is meeting milestones and requirements and supports decisions about engagement, additional disbursements, and future funding. Users can copy the response or select Generate to request another version.","Administrators add the Einstein Summary component to the Individual Application and Funding Award record pages and configure the corresponding Record Summary prompt templates. Users require the documented Context Service, Einstein for Service Innovations, Grantmaking Manager, and Prompt Template User access to use these features. Board Version of Grant Application and Funding Award Summary each support up to 100 related records as grounding data. Blank source fields aren’t omitted from response generation and can result in incomplete output."],connections:[{"planet":"grantmaking","desc":"AI features summarize grant applications and funding awards"},{"planet":"agentforce","desc":"Agentforce agents can leverage Einstein AI for grant-related queries"}]},
    {id:"case-notes-ai",name:"Notes & Program Summaries",icon:"\u{1F4DD}",desc:"Notes & Program Summaries provides Notes Summary and Program Benefits Summary capabilities in Public Sector Solutions. Notes Summary consolidates interaction information about constituents, participants, or grantees and can surface actions or tasks recorded in notes. Program Benefits Summary drafts a stakeholder-facing description of program progress based on Benefit and Program data. Both capabilities use Record Summary prompt templates and are limited to 100 related records used as grounding data.",tags:["InteractionSummary"],docs:["Notes Summary uses the Summarize Notes prompt template on an Account record page. Its grounding sources are Interaction Summary, Person Account, and Program. Case managers, including users working with investigative cases, can use the generated summary to review prior interactions and identify actions or tasks that were recorded but not completed. The feature supports Benefit Management, Investigative Case Management, and Social Program Management workflows.","Program Benefits Summary uses the Summarize Program and Benefits prompt template on a Program record page. Its grounding sources are Benefit and Program. Program managers can use the generated draft to describe program progress to internal and external stakeholders. The source list does not include benefit enrollment, disbursement, or outcome data.","Administrators configure Notes Summary and Program Benefits Summary as Record Summary prompt templates in the Einstein Summary component. Users can select Copy to reuse generated text or Generate to request another version. These Record Summary features do not save responses to designated record fields; saving an LLM response to a record field is available only for Field Generation prompt templates. Notes Summary and Program Benefits Summary each support up to 100 related records as grounding data."],connections:[{"planet":"investigative_cases","desc":"Notes summaries support investigative case management"},{"planet":"social_programs","desc":"Program summaries describe benefit program progress to stakeholders"}]}
  ],
  dataFlow: ["Assign the required Public Sector Solutions add-on licenses and permission sets.","Prepare Salesforce records and Data 360 grounding data for the AI models.","Configure prompt templates, template-triggered flows, and Einstein Summary record-page components.","Generate benefit application and household overviews, license summaries, prior violation reports, grant summaries, notes summaries, and program benefits summaries.","Review, copy, or edit responses, and save only Field Generation responses to configured record fields.","Let Agentforce agents leverage the configured Einstein AI capabilities in supported workflows."],
  connections: [{"planet":"benefit_management","desc":"Application history and household overviews for benefit management"},{"planet":"licensing_and_permitting","desc":"License compliance summaries for permit tracking"},{"planet":"inspections","desc":"Prior violation reports for inspection management"},{"planet":"investigative_cases","desc":"Notes summaries for investigative case managers"},{"planet":"grantmaking","desc":"Board versions and funding award summaries for grantmaking"},{"planet":"agentforce","desc":"Agentforce agents leverage Einstein AI capabilities"},{"planet":"setup_and_security","desc":"Einstein generative AI requires specific permission sets and add-on licenses"},{"planet":"data_360","desc":"Data Cloud provides grounding data for AI models"}]
},

data_360: {
  packages: ["core"],
  name: "Data 360",
  icon: "\u{1F300}",
  color: "#0d9488",
  description: "Data 360 integrates Public Sector Solutions records with external sources to create comprehensive constituent and employee profiles. It unifies eligibility data from multiple benefit systems, combines applicant history with employee performance and pay data, and aggregates investigative case information from multiple agencies. Unified data enhances Einstein predictions and summaries, while enriched profiles power CRM Analytics dashboards and other analytical experiences. Data 360 setup and connector permissions govern ingestion, and the grantmaking data bundle maps grant objects into Data 360 alongside other Public Sector Solutions data kits.",
  components: [
    {id:"pss-data-kit",name:"PSS Data Kit",icon:"\u{1F4E6}",desc:"The PSS Data Kit provides a starting point for bringing Public Sector Solutions records into Data 360. It includes predefined data model objects, data bundles, data streams, and mappings for more than 100 Public Sector Solutions objects. The available data kits cover benefit management, case management, investigative case management, licenses and permits, provider management, common data, and talent recruitment management. Administrators can deploy complete data kits or select individual data bundles and streams for their implementation.",tags:["Account","Contact","Individual"],docs:["The PSS Data Kit organizes ingestion assets into data kits, data bundles, and data streams. A data kit can contain one or more data bundles, and each data bundle contains a collection of data streams. The predefined streams map Salesforce source objects to corresponding Data 360 data model objects and provide a flow of near real-time data from Public Sector Solutions to Data 360. Examples include Account, Contact, IndividualApplication, BenefitDisbursement, Case, and Visit source objects.","Before deployment, configure Data 360 and the Salesforce CRM connector. In Data Cloud Setup, select Salesforce CRM, click New, and then click Connect to a Salesforce Org. In the source org, update the Data Cloud Salesforce Connector permission set with Read, View All Records, and field-level Read Access for the objects and fields required by each use case. Enable the documented org settings and system permissions for each data kit before ingesting its data.","Deploy an entire data kit from Data Kits in Setup, or deploy an individual data bundle from the Data Streams tab in the Data 360 app. When deploying a bundle, select the connected Salesforce CRM org, the data space, the required streams, and the fields to include. All fields in a data bundle are deployed by default, but administrators can select specific fields and later add or remove mappings. The grantmaking data bundle maps grant objects to Data 360 for unified grantmaking data use cases."],connections:[{"planet":"setup_and_security","desc":"Requires Data Cloud Admin permissions and connector setup"},{"planet":"benefit_management","desc":"Maps benefit and application objects for eligibility analysis"}]},
    {id:"data-streams-mapping",name:"Data Streams & Mapping",icon:"\u{1F504}",desc:"Data Streams & Mapping defines how Public Sector Solutions source records flow into Data 360 data lake objects and data model objects. Predefined streams map source fields to corresponding fields in the Data 360 data model, and stream names include the connected org alias as a suffix. Administrators can retain the supplied mappings, add mappings for other fields, or remove mappings that their implementation doesn’t use. The mappings support common constituent, benefit, case, provider, recruitment, licensing, and inspection data.",tags:["IndividualApplication","BenefitDisbursement","Case","Visit"],docs:["Each predefined data stream identifies a Public Sector Solutions source object and one or more target data model objects. For example, Account_OrgAlias maps Account to Account and Party, Contact_OrgAlias maps Contact to AccountContact, Individual, and Party, and Individual_OrgAlias maps Individual to Individual. IndividualApplication_OrgAlias maps IndividualApplication to BenefitApplication, while Case_OrgAlias maps Case to Case. These mappings establish the modeled data used for unified profiles and downstream insights.","After a stream is deployed, administrators can open its data mapping and connect source data lake object fields to target data model object fields. The supplied mappings cover corresponding fields, but other fields can be mapped as required. Configuration must preserve compatible data types, and some documented implementations require formula fields to resolve source and target type differences. The stream name uses OrgAlias to identify the Public Sector Solutions org that supplies the data.","Different data kits require different org settings and connector system permissions. Benefit Management requires access to program, benefit, disbursement, care plan, provider, and search capabilities, while Investigative Case Management requires access to investigative cases and evidence management. Talent Recruitment Management requires recruiting and hiring access, Discovery Framework, Action Plans, compliant data sharing, and Document Checklist access. The Public Sector Solutions Common data kit supplies shared records and relationships used across these implementations."],connections:[{"planet":"social_programs","desc":"Streams ingest program enrollment and referral data for analysis"},{"planet":"investigative_cases","desc":"Aggregates case and complaint data from multiple agencies"}]},
    {id:"external-data-ingestion",name:"External Data Ingestion",icon:"\u{1F310}",desc:"External Data Ingestion connects non-Salesforce sources to Data 360 so agencies can combine external records with Public Sector Solutions data. Supported approaches include prebuilt connectors, Ingestion API, Data Source Configuration in Data 360, and MuleSoft Anypoint Connector for Salesforce Data 360. Agencies can use these connections to bring eligibility, employment, case, complaint, and other relevant information into unified profiles. The resulting data can support cross-system analysis without limiting the profile to records held in the Public Sector Solutions org.",tags:["Account","Contact"],docs:["Connect the external source to Data 360 by using the ingestion option appropriate for that source. The documented options include Ingestion API, Data Source Configuration in Data 360, Connect and Ingest Data in Data 360, and MuleSoft Anypoint Connector for Salesforce Data 360. Configure the connection and ingestion according to the source system and the agency’s Data 360 strategy. Data spaces and Data 360 permission sets govern access to the ingested data.","External ingestion supports use cases that require information from multiple systems or organizations. Benefit Management can unify eligibility data from multiple benefit systems to understand constituent needs, evaluate program eligibility, and identify inconsistencies or potential fraud. Investigative Case Management can combine Salesforce case and complaint information with previous cases or complaints managed by other agencies. Talent Recruitment Management can combine applicant history in Salesforce with employee performance and pay history from other systems."],connections:[{"planet":"talent_recruitment","desc":"Aggregates applicant history with employee performance from external HR systems"},{"planet":"provider_management","desc":"Ingests provider data from external credentialing systems"}]},
    {id:"analytics-ai-insights",name:"Analytics & AI-Driven Insights",icon:"\u{1F4A1}",desc:"Analytics & AI-Driven Insights uses unified Data 360 profiles to support analysis, predictive modeling, and operational decision-making in Public Sector Solutions. Agencies can prepare and model data, unify source profiles, enhance data with insights, and contextualize it for analytics and automation. Unified constituent and employee data improves the grounding available to Einstein predictions and summaries. Enriched profiles can also power CRM Analytics dashboards and other reports that expose actionable service, case, benefit, and workforce insights.",tags:["Account","Contact","Individual"],docs:["Data 360 provides capabilities to prepare and model data, unify source profiles, enhance data with insights, and contextualize data for use. Agencies can use AI models and search with AI, automation, and analytics, then build and share functionality or activate segments. Data ingestion, unification, and real-time processing support comprehensive constituent and employee profiles. These profiles can streamline case management, benefit applications, and public safety efforts.","Advanced analytics and AI-driven insights support predictive modeling and resource optimization. Dashboards and custom reports provide actionable information based on the unified data, while Data 360 data governance and access controls support security and compliance. CRM Analytics can use enriched constituent and operational information to provide dashboards for caseloads, case trends, community impact, caseworker efficiency, licensing, permitting, and inspections. Data 360 permission sets and data-space access determine which users can work with the underlying data.","Public Sector Solutions features can surface Data 360 insights alongside operational records. The Unified Constituent Profile for Benefit Management includes integrated Data 360 insights such as financial summaries, benefit history, and eligibility-related data on a constituent account page. The same page experience can combine those insights with Einstein-generated summaries and priority alerts. Unifying benefit, investigative, recruitment, and employee data gives AI features broader grounded context for predictions and summaries."],connections:[{"planet":"einstein_ai","desc":"Unified data powers Einstein AI predictions and generative summaries"},{"planet":"crm_analytics","desc":"Enriched data feeds CRM Analytics dashboards for deeper insights"}]}
  ],
  dataFlow: ["Configure Data 360, data spaces, the Salesforce CRM connector, and connector permissions.","In Data Cloud Setup, select Salesforce CRM, click New, and connect to a Salesforce org.","Enable required object and field access, then deploy the PSS Data Kit and the grantmaking data bundle.","Connect external sources and ingest eligibility, interagency case, applicant, employee performance, and pay data.","Map and unify the ingested records into comprehensive constituent and employee profiles.","Use the unified data for Einstein predictions and summaries and for CRM Analytics dashboards."],
  connections: [{"planet":"setup_and_security","desc":"Data Cloud configuration and connector permissions"},{"planet":"benefit_management","desc":"Unifies eligibility data from multiple benefit systems"},{"planet":"investigative_cases","desc":"Aggregates case data from multiple agencies for analysis"},{"planet":"talent_recruitment","desc":"Combines applicant and employee performance data"},{"planet":"einstein_ai","desc":"Unified data enhances AI predictions and summaries"},{"planet":"crm_analytics","desc":"Enriched profiles power analytics dashboards"},{"planet":"grantmaking","desc":"Grantmaking data bundle maps grant objects to Data Cloud"}]
},

experience_cloud: {
  packages: ["core"],
  name: "Experience Cloud",
  icon: "\u{1F310}",
  color: "#d946ef",
  description: "Public Sector Solutions provides exactly seven Experience Cloud site templates: Benefit Assistance, Career Site, Emergency Response Site, Employee Site, Grantmaking, Licenses And Permits, and Service Provider Portal. Together, these templates support constituent access to benefits, complaints, licenses, permits, grants, emergency assistance, and jobs, as well as recruitment collaboration and provider service delivery. The templates provide preconfigured pages and components that administrators can customize in Experience Builder. Required profiles, permission sets, permission set groups, sharing settings, and licenses are configured and assigned separately rather than being deployed by every template.",
  components: [
    {id:"benefit-assistance-site",name:"Benefit Assistance Site",icon:"\u{1F3E5}",desc:"The Benefit Assistance Site gives constituents self-service access to benefit applications, complaints, care plans, tasks, and application records. It supports Benefit Finder eligibility prescreening, guided benefit application intake, change-of-circumstances reporting, and benefit recertification. The template also supports complaint intake for justice and investigative case management. Access profiles, permission sets, permission set groups, sharing settings, and guest-user permissions are configured separately from the template.",tags:["IndividualApplication","PublicComplaint","CarePlan"],docs:["The Benefit Assistance Experience Cloud site template includes Benefits, Complaints, Care Plans, Tasks, and Applications pages, in addition to standard login and registration pages. Constituents can use Benefit Finder to complete an eligibility assessment based on criteria configured with an Omniscript, a decision matrix, and an expression set. The site also lets constituents apply for benefits, view assigned benefits, track applications, access care plans, and file or view complaints.","Public Sector Solutions provides guided processes for benefit application intake, reporting a change of circumstances, and benefit recertification. These processes use Discovery Framework assessment questions, Omniscripts, Omnistudio Integration Procedures, and Omnistudio Data Mappers to collect information and store application data. Constituents can review or update household and income information, upload supporting documents, and submit applications for caseworker review.","Before creating the site, enable Digital Experiences and complete the applicable benefit-management and guided-flow setup. Clone and customize the Customer Community Plus User profile, configure object access and sharing settings, and set up self-registration to create person accounts when required. Assign the documented permission sets to site users separately, or assign the Benefit_Management_Constituent permission set group; the Benefit Assistance template itself does not deploy these permissions."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_benefit_assistance_comm_settings.htm&language=en_US&type=5",connections:[{"planet":"benefit_management","desc":"Constituents submit benefit applications through the portal"},{"planet":"social_programs","desc":"Portal displays program enrollment and care plan information"}]},
    {id:"licenses-permits-site",name:"Licenses & Permits Site",icon:"\u{1F4DC}",desc:"The Licenses & Permits Site enables constituents to assess authorization requirements, apply for and renew licenses or permits, and track related records. It also supports license-holder searches, complaint filing, inspection history, fee history, and application approval history. The Licenses And Permits template supplies preconfigured pages, while Public Sector Solutions components and list views provide the corresponding self-service experiences. User profiles, permission sets, sharing settings, and guest access must be configured separately.",tags:["BusinessLicenseApplication","BusinessLicense","PublicComplaint"],docs:["The Licenses And Permits Experience Cloud site template includes pages for assessing license or permit needs, applying, renewing, viewing required permits, searching for authorization holders, filing complaints, and reviewing applications and licenses. It also provides pages for complaint history and inspection history. Administrators can add dedicated Lightning web components from the Public Sector process library to support prescreening, business and individual applications, renewal, searches, and complaint intake.","Public Sector Solutions can expose inspection details, regulatory transaction fee history, approval history, and issued license or permit records through configured site pages and Record List components. The Permits component shows the business regulatory authorization types and dependencies defined in the org, helping constituents understand requirements for a business type. Submitted Omniscript forms can create Business License Application or Individual Application records that continue through agency review, inspections, fees, approvals, and issuance.","Complete the licensing and permitting prerequisites, enable Digital Experiences, and create the site from the Licenses And Permits template. Configure self-registration, the customer community profile, object access, sharing settings, and any required guest-user access. Assign the documented permission sets to Experience Cloud site users separately, or assign the Licensing_Permitting_Constituent permission set group; these permissions are prerequisites and are not deployed by the template."],connections:[{"planet":"licensing_and_permitting","desc":"Self-service portal for the full license and permit lifecycle"},{"planet":"inspections","desc":"Constituents can view their inspection history through the portal"}]},
    {id:"career-and-employee-sites",name:"Career & Employee Sites",icon:"\u{1F464}",desc:"The Career & Employee Sites support external job seekers and internal participants in the recruitment process. The Career Site lets applicants search for openings, apply through guided forms, upload documents, and track applications and employment offers. The Employee Site gives hiring managers and interviewers pages for requisitions and applicant evaluations. Separately, an Employee Portal can provide government employees with HR Service and Public Sector Solutions capabilities.",tags:["RecruitmentPosting","RecruitmentRequisition","JobPosition"],docs:["The Applicant Site for Recruitment template provides a career site where job seekers can learn about an organization, search job postings, review requirements, and apply for positions. Criteria-Based Search and Filter can match postings to preferences such as title, location, pay range, work schedule, occupation, and position type. The job application guided flow captures personal, education, work experience, competency, and resume information, while application pages let applicants track active, closed, and draft applications.","The Employee Site for Recruitment template includes Requisitions and Evaluations pages for hiring managers and interviewers. Hiring managers can review and approve recruitment requisitions and postings, while assigned evaluators can review application details and complete Dynamic Assessments. Employee site users are created with the appropriate internal profile and role, and receive permissions through separately assigned permission sets or the applicable Talent_Recruitment_Management permission set group.","Employee Experience for Public Sector Solutions can also use an Employee Portal to provide HR Service and Public Sector Solutions capabilities to government employees. Supported scenarios include employee access to benefits, grants, inspections, licenses and permits, provider services, and talent recruitment processes. Implementers create the required Experience Cloud sites and workflows, assign a Salesforce Platform license to each employee, grant Case access where needed, and assign the Employee_Experience_User permission set group or the required individual permission sets."],connections:[{"planet":"talent_recruitment","desc":"Public-facing job search and internal hiring manager workflows"},{"planet":"employee_experience","desc":"Employee portal integrates with HR Service and PSS capabilities"}]},
    {id:"grantmaking-site",name:"Grantmaking Site",icon:"\u{1F4B8}",desc:"The Grantmaking Site supports collaboration among grantmakers, grantseekers, and external reviewers throughout the funding lifecycle. Grantmakers can publish and manage funding opportunities, while grantseekers can discover opportunities, submit applications, and report on grants. External reviewers can assess grant applications through the site. Public Sector Solutions combines the site experience with grant, budget, application, review, award, and progress-report processes.",tags:["FundingOpportunity","ApplicationForm","FundingAward"],docs:["The Grantmaking Experience Cloud site template creates a portal where grantmakers can post and manage funding opportunities. Grantseekers can discover opportunities, apply for funding, and report progress against goals and KPIs. External reviewers can use the site to assess submitted grant applications.","Grantmaking uses dynamic application forms and built-in automation to reduce paper-based processing and accelerate reviews and approvals. Form Framework can organize funding applications into multiple phases or sections, provide reviewer workspaces, and support progress-report forms for grant recipients. Site access and record collaboration must be configured for the grant seekers, reviewers, and grantmaking staff who participate in these processes."],connections:[{"planet":"grantmaking","desc":"Online portal for the full grant application and reporting lifecycle"}]},
    {id:"emergency-provider-sites",name:"Emergency & Provider Sites",icon:"\u{26A1}",desc:"The Emergency & Provider Sites address crisis assistance for constituents and service-delivery collaboration with provider organizations. The Emergency Response Site publishes emergency program information and incident updates and accepts requests for assistance, licenses, permits, or critical supplies. The Service Provider Portal lets certified providers process referrals, manage schedules and sessions, track attendance and service delivery, and maintain provider information. These sites connect constituent requests and provider activity with the corresponding Public Sector Solutions records and agency workflows.",tags:["Visit","Referral"],docs:["The Emergency Response Site supports public access to emergency program information and incident updates during times of crisis. Constituents can request emergency assistance and apply for relevant licenses, permits, and assistance programs, while businesses can request critical supplies or permits. After a permit is approved, inspectors can use the Inspection app to verify that a site complies with applicable health and safety ordinances.","The Service Provider Portal template includes Clients, Schedules, and Attendance pages in addition to standard login and registration pages. Providers can review referral requests, request authorization, view authorized clients and assigned benefits, propose benefit schedules, enroll constituents in sessions, and record attendance. Benefit disbursement records track session enrollment, attendance status, and delivered quantities so that caseworkers can monitor service delivery.","Provider portal setup requires Provider Management, Program and Benefit Management, and the applicable case-management settings. Administrators clone and customize a Partner Community User profile, create partner users, configure sharing for provider records, and separately assign Omnistudio Experience Cloud User and Provider Management For Partner or the Social_Program_Management_Provider permission set group. Chatter feed tracking can be enabled for Benefit Assignment, Benefit Schedule, Benefit Session, and Referral so providers can view relevant record updates on the site."],connections:[{"planet":"emergency_and_assets","desc":"Emergency portal for crisis-time applications and assistance"},{"planet":"provider_management","desc":"Providers manage referrals and service delivery through the portal"}]}
  ],
  dataFlow: ["Select the appropriate Experience Cloud template and configure its preconfigured pages and components.","Configure profiles, sharing, self-registration, guest access, and permission assignments separately from the template.","Publish self-service benefit, complaint, license, permit, emergency assistance, grant, and job application experiences.","Route submitted applications, complaints, referrals, and reviews into the corresponding Public Sector Solutions workflows.","Enable hiring teams, grant reviewers, caseworkers, inspectors, and service providers to process and collaborate on submitted records.","Expose statuses, decisions, care plans, inspections, awards, schedules, and service-delivery updates through the appropriate constituent, provider, or employee site."],
  connections: [{"planet":"licensing_and_permitting","desc":"Self-service license and permit applications"},{"planet":"benefit_management","desc":"Constituent portal for benefit applications and complaints"},{"planet":"talent_recruitment","desc":"Career site for job seekers and employee site for hiring managers"},{"planet":"grantmaking","desc":"Grant application portal for seekers and reviewers"},{"planet":"emergency_and_assets","desc":"Emergency response portal for crisis assistance"},{"planet":"provider_management","desc":"Service provider collaboration portal"},{"planet":"employee_experience","desc":"Employee portal for HR service and PSS capabilities"}]
},

crm_analytics: {
  packages: ["core"],
  name: "CRM Analytics",
  icon: "\u{1F4CA}",
  color: "#84cc16",
  description: "CRM Analytics in Public Sector Solutions provides prebuilt analytics for licensing, permitting, inspections, benefit programs, investigative caseloads, community impact, and caseworker efficiency. The Analytics for Licenses, Permits, and Inspections app includes Compliance Insights, Executive Summary, Department Summary, and Account Insights, while the Caseworker Productivity App includes Workload Management Analytics and Case Analytics. Workload Management Analytics supports SLA monitoring, workload distribution, staffing decisions, benefit disbursement analysis, and cross-caseworker comparison; Case Analytics is limited to time spent in each case status and total case-processing time. Administrators enable CRM Analytics, assign permission sets, validate source data and field access, deploy the apps, and schedule recurring refreshes or data sync.",
  components: [
    {id:"license-permit-analytics",name:"License, Permit & Inspection Analytics",icon:"\u{1F50D}",desc:"License, Permit & Inspection Analytics is delivered through the Analytics for Licenses, Permits, and Inspections app in Public Sector Solutions. It provides Compliance Insights, Executive Summary, Department Summary, and Account Insights dashboards for regulatory operations. These dashboards analyze applications, licenses, inspections, complaints, violations, enforcement actions, fees, regulatory authorities, and account activity.",tags:["BusinessLicenseApplication","Visit","RegulatoryCodeViolation","PublicComplaint"],docs:["The Analytics for Licenses, Permits, and Inspections app provides intelligent insights that help agencies improve departmental productivity and constituent satisfaction. Compliance Insights tracks inspection performance and trends in violations and enforcement actions. Executive Summary monitors agency performance through application, license, fee, inspection, violation, and complaint trends. Department Summary highlights department performance and identifies applications and inspections that need attention, while Account Insights shows regulatory activity associated with a particular account.","Compliance Insights supports analysis of inspection activity, team performance, violations, complaints, and enforcement actions. Executive Summary shows how applications and issued licenses change over time, how applications are distributed across business types, license types, and regulatory authorities, and which accounts lead by licenses or fees. Department Summary compares performance with a previous period and identifies items requiring attention. Account Insights reports open violations, how long violations remain open, and the status of applications, licenses, inspections, violations, and complaints.","To create the app, the org must contain at least one record in Business License Application, Individual Application, Public Complaint, Regulatory Transaction Fee, or Visit. The Analytics for Licenses, Permits, and Inspections template supports Salesforce and external data, standard and custom objects, and up to 10 billion rows with CRM Analytics Plus. Users can customize or create dashboards, datasets, and CRM Analytics apps. Dashboards can also be embedded in Public Sector Solutions Lightning pages by using the CRM Analytics Dashboard component."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_lpi_analytics_deploy_and_use.htm&type=5&language=en_US",connections:[{"planet":"licensing_and_permitting","desc":"Dashboards visualize license application trends and fee revenue"},{"planet":"inspections","desc":"Compliance and inspection trend analytics across the agency"}]},
    {id:"caseworker-productivity",name:"Caseworker Productivity Analytics",icon:"\u{1F4C8}",desc:"Caseworker Productivity Analytics is provided by the Caseworker Productivity App in Public Sector Solutions. Its Workload Management Analytics dashboard presents caseload, case trend, SLA, benefit, community impact, and caseworker performance information. Agencies can use these insights to distribute work, make staffing decisions, improve team productivity, prioritize cases by community impact, and allocate resources based on benefits disbursed.",tags:["Case","BenefitDisbursement","IndividualApplication","Referral"],docs:["Workload Management Analytics includes Summary, SLA Management, Benefits, and Leaderboard tabs. Summary reports total, new, open, and closed cases, average closure time, case trends, case distribution, stage duration, and cases requiring immediate attention. SLA Management shows transition times between stages and the average time cases remain in a particular status. Benefits reports individuals and households served, monetary and nonmonetary benefits delivered, active care plans, and benefit distribution across programs.","The Leaderboard provides comparisons of caseworker performance based on new, open, and total assigned cases. It also shows each team member’s caseload and community impact. These cross-caseworker comparisons are part of Workload Management Analytics and support workload distribution and staffing or resource decisions. Managers can filter the dashboard by caseworker, time frame, ZIP code, and other available criteria.","For Benefit Management, the Caseworker Productivity App uses the PSS Benefit Management and PSS Workload Management datasets, along with the PSS Trending Recipe and PSS Workload & Benefits Management Recipe. Source records include Account, Benefit, Benefit Assignment, Benefit Disbursement, Care Plan, Case, Goal Assignment, Goal Definition, Individual Application, Party Relationship Group, Program, Program Enrollment, Public Complaint, and Referral. For Investigative Case Management, the app uses the PSS Workload Management dataset and the same two recipes, with data from Account, Case, Complaint Case, Individual Application, Referral, and User. These objects must contain records to populate the dashboard metrics, charts, and widgets."],connections:[{"planet":"benefit_management","desc":"Tracks benefit disbursement amounts and community impact"},{"planet":"social_programs","desc":"Monitors program enrollment and case distribution metrics"}]},
    {id:"case-analytics",name:"Case Analytics",icon:"\u{23F1}",desc:"Case Analytics is a dashboard in the Caseworker Productivity App for examining the processing time of an individual case. It shows how many days the case has spent in each status and how many days have been spent processing the case. Caseworkers can use this timing information to help ensure that case processing meets service-level agreement requirements.",tags:["Case"],docs:["Case Analytics provides case-level processing-time insights. The dashboard charts answer two documented questions: how many days the case has spent in each status, and how many days have been spent processing the case. Cross-caseworker performance comparison belongs to the Workload Management Analytics Leaderboard, not Case Analytics. Staffing and resource decisions are likewise supported by Workload Management Analytics.","To make the dashboard available from a case, add the CRM Analytics Dashboard component to the Case record page and select Case Analytics. Users need Public Sector Access to access cases and the CRM Analytics Plus User and TCRM for Public Sector User permission sets to view the dashboard. The dashboard is installed with the Caseworker Productivity App, but it must be added separately to the Case record page."],connections:[{"planet":"investigative_cases","desc":"Tracks investigative case processing time and SLA compliance"},{"planet":"benefit_management","desc":"Monitors benefit case processing duration against SLAs"}]},
    {id:"analytics-setup",name:"Analytics Setup & Data Sync",icon:"\u{2699}",desc:"Analytics Setup & Data Sync covers permissions, CRM Analytics enablement, app deployment, dashboard embedding, and recurring data updates for Public Sector Solutions analytics. Administrators create the Analytics for Licenses, Permits, and Inspections app from its template and install the Caseworker Productivity App through guided setup. Source-object records and field access must be available before dashboards and datasets can populate successfully.",tags:["Account","Case","Visit"],docs:["Administrators who create and manage analytics apps require the CRM Analytics Plus Admin and TCRM for Public Sector Admin permission sets. Dashboard users require the CRM Analytics Plus User and TCRM for Public Sector User permission sets. Before creating or installing an app, enable CRM Analytics from the Analytics Getting Started page in Setup. Public Sector Solutions security configuration remains relevant because users also need access to the source records and features represented in the dashboards.","Create the license, permit, and inspection analytics app in Analytics Studio by selecting the Analytics for Licenses, Permits, and Inspections template. Analytics Studio performs a compatibility check against the org’s data before creating the app. After creation, share the app with users as Viewers, Editors, or Managers according to their responsibilities. The app can analyze licensing and permitting trends as well as inspection compliance, violations, enforcement actions, and account activity.","Install the Caseworker Productivity App from Set Up Caseworker Productivity Analytics in Setup. Guided setup installs Workload Management Analytics and Case Analytics and adds Workload Management Analytics to the Public Sector Solutions Benefit Management app. Add Case Analytics to the Case record page separately by using the CRM Analytics Dashboard component. The app supports workload and case-processing analytics for both Benefit Management and Investigative Case Management when their required source data is present.","For license, permit, and inspection analytics, grant the Analytics Cloud Integration User profile visibility to the required fields on the documented source objects. Keep that app current by scheduling a daily data refresh outside normal work hours. Keep caseworker productivity analytics current by scheduling data sync and recipes to run at regular intervals. Data 360 can integrate Public Sector Solutions data with external sources and support advanced analytics and AI-driven insights from unified constituent and employee data."],connections:[{"planet":"setup_and_security","desc":"Analytics permission sets and CRM Analytics enablement"},{"planet":"data_360","desc":"Data Cloud integration enriches analytics datasets"}]}
  ],
  dataFlow: ["Enable CRM Analytics and assign the required admin and user permission sets.","Populate the required licensing, inspection, benefit management, investigative case, and Case records.","Create the Analytics for Licenses, Permits, and Inspections app and install the Caseworker Productivity App.","Embed the appropriate CRM Analytics dashboards on Lightning pages and Case record pages.","Schedule app refreshes, data sync, and recipes to keep analytics current.","Integrate enriched Data 360 data with external sources to support deeper analytics and AI-driven insights."],
  connections: [{"planet":"licensing_and_permitting","desc":"License, permit, and inspection trend dashboards"},{"planet":"inspections","desc":"Compliance and violation enforcement analytics"},{"planet":"benefit_management","desc":"Caseworker productivity and community impact metrics"},{"planet":"investigative_cases","desc":"Workload management and case processing analytics"},{"planet":"setup_and_security","desc":"Permission sets and CRM Analytics enablement"},{"planet":"data_360","desc":"Enriched Data Cloud data powers deeper analytics"}]
},

emergency_and_assets: {
  packages: ["core"],
  name: "Emergency & Assets",
  icon: "\u{1F6A8}",
  color: "#dc2626",
  description: "Manages emergency program responses and physical asset tracking for public sector agencies. The emergency management capability enables agencies to create Experience Cloud sites for crisis response, providing constituents with emergency program information, incident updates, permit applications, and assistance programs like food delivery services. Inspectors use the mobile Inspection app to verify site compliance with health and safety ordinances. Businesses can request critical supplies and permits through the portal to protect employee and customer safety.",
  components: [
    {id:"emergency-program-mgmt",name:"Emergency Program Management",icon:"\u{26A0}",desc:"Creates Experience Cloud sites highlighting emergency programs and services available to public agencies, hospitals, and constituents during crises. Allows constituents to request permits for building access and apply for assistance programs. Responders use the Inspection app to deliver emergency services efficiently.",tags:["Visit","Visitor"],docs:["Emergency Program Management creates Experience Cloud sites highlighting emergency programs and services available during crises. Constituents can request permits for building access, apply for assistance programs such as food delivery services, and access real-time incident updates. Public agencies, hospitals, and community organizations use the portal to coordinate emergency response efforts.","The feature integrates with licensing workflows for emergency permit applications. When businesses need to resume operations during an emergency, they submit permit requests through the portal that are routed through the standard licensing approval process. Responders and inspectors use the mobile Inspection app to deliver emergency services and verify compliance efficiently.","Emergency program information is published through the Emergency Response Site Experience Cloud template, which provides preconfigured pages for program listings, application forms, and status tracking. The site can be rapidly deployed during a crisis to provide constituents with centralized access to all available emergency assistance."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_concept_emergency_program_management.htm&type=5&language=en_US",connections:[{"planet":"experience_cloud","desc":"Emergency Response Site template for constituent self-service"},{"planet":"licensing_and_permitting","desc":"Emergency permit applications processed through licensing workflows"}]},
    {id:"emergency-inspections",name:"Emergency Inspections",icon:"\u{1F50E}",desc:"After emergency permits are approved, inspectors use the mobile Inspection app to verify that sites comply with local health and safety ordinances. Businesses requesting permits during emergencies are subject to on-site verification before operations can resume.",tags:["Visit"],docs:["Emergency Inspections use the mobile Inspection app to verify that sites comply with local health and safety ordinances after emergency permits are approved. Businesses requesting operational permits during emergencies are subject to on-site verification before they can resume operations, ensuring that employee and customer safety standards are maintained even during crisis conditions.","The emergency inspection workflow leverages the standard inspection framework, using Visit records, action plan templates, and assessment indicators configured for emergency-specific compliance requirements. Inspectors access their assignments through the mobile Inspection Management app, which supports offline data capture and signature collection.","Inspection results feed back into the emergency permit approval workflow. If a site fails to meet health and safety requirements, the permit remains pending until violations are corrected and a follow-up inspection confirms compliance. This integration ensures that emergency operations do not compromise public safety standards."],connections:[{"planet":"inspections","desc":"Emergency inspection visits leverage the standard inspection framework"},{"planet":"licensing_and_permitting","desc":"Inspection results feed back into permit approval workflows"}]},
    {id:"crisis-resource-mgmt",name:"Crisis Resource Management",icon:"\u{1F4E6}",desc:"Enables businesses and agencies to request critical supplies during emergencies to ensure the health and safety of employees and customers. Tracks resource requests, allocation of supplies, and distribution through the portal, helping coordinate emergency logistics across multiple agencies.",tags:["Visitor","Visit"],docs:["Crisis Resource Management enables businesses and agencies to request critical supplies during emergencies to ensure the health and safety of employees and customers. The feature tracks resource requests, allocation of supplies, and distribution through the Emergency Response portal, helping coordinate emergency logistics across multiple agencies and service areas.","Action plans coordinate emergency resource distribution tasks, providing structured workflows for intake, approval, fulfillment, and delivery of requested supplies. The Visitor and Visit objects track access to emergency distribution sites and record resource allocation activities, creating an audit trail of emergency response actions.","Emergency assistance programs managed through crisis resource management operate alongside regular benefit programs in the social programs framework. This integration allows agencies to leverage existing program infrastructure for emergency response while maintaining separate tracking and reporting for crisis-specific activities."],connections:[{"planet":"common_features","desc":"Action plans coordinate emergency resource distribution tasks"},{"planet":"social_programs","desc":"Emergency assistance programs managed alongside regular benefit programs"}]},
    {id:"site-location-tracking",name:"Site & Location Tracking",icon:"\u{1F4CD}",desc:"Uses polygons and visit records to define geographic boundaries for emergency zones, track visitor access to restricted areas, and manage site-level information for emergency operations. Supports mapping of affected areas and coordination of field responders across multiple locations.",tags:["Polygon","Visit","Visitor"],docs:["Site and Location Tracking uses Polygon objects to define geographic boundaries for emergency zones and restricted areas. Visit and Visitor records track access to these zones, enabling agencies to monitor who enters emergency areas and coordinate field responder activities across multiple locations during crisis response operations.","The geographic boundary capabilities support mapping of affected areas, defining emergency zone perimeters, and visualizing the spatial extent of crisis events. Maps and timeline components display emergency site data, providing responders and coordinators with visual context for their response activities.","Location-based inspection scheduling uses geographic data to assign inspectors to emergency zones based on proximity and jurisdiction. This ensures efficient deployment of inspection resources during emergencies when multiple sites may need simultaneous compliance verification and safety assessments."],connections:[{"planet":"inspections","desc":"Location-based inspection scheduling for emergency zones"},{"planet":"common_features","desc":"Maps and timeline components visualize emergency site data"}]}
  ],
  dataFlow: ["Agency creates an Emergency Response Experience Cloud site during a crisis","Constituents and businesses submit permit requests and assistance applications through the portal","Emergency permits are routed through licensing workflows for approval","Inspectors use the mobile Inspection app to verify site compliance with safety ordinances","Resource requests are tracked and supplies distributed to affected areas","Emergency zones are mapped using polygons and field responders are coordinated"],
  connections: [{"planet":"experience_cloud","desc":"Emergency Response Site template for crisis portals"},{"planet":"licensing_and_permitting","desc":"Emergency permit applications and approvals"},{"planet":"inspections","desc":"On-site inspections for emergency compliance verification"},{"planet":"social_programs","desc":"Emergency assistance programs for affected constituents"},{"planet":"common_features","desc":"Action plans and maps for emergency coordination"}]
},

employee_experience: {
  packages: ["core"],
  name: "Employee Experience",
  icon: "\u{1F465}",
  color: "#78716c",
  description: "Employee Experience gives government employees access to HR Service, Agentforce IT Service, and employee-facing Public Sector Solutions workflows. Experience Cloud sites provide entry points for benefits, grants, inspections, licensing and permitting, provider services, employee service, and internal recruitment. HR Service addresses employee queries and service requests, while Agentforce IT Service provides standardized support through Slack, Microsoft Teams, Experience Cloud, email, and chat. Platform licenses, permission set groups, capability-specific permission sets, and Agentforce access determine which services each employee can use.",
  components: [
    {id:"hr-service-integration",name:"HR Service Integration",icon:"\u{1F4BC}",desc:"HR Service Integration connects HR Service with Public Sector Solutions to help government organizations address employee queries and service requests. It supports HR, legal, ethics, procurement, and other internal processes intended to improve employee connectivity, effectiveness, and productivity. Employees can access HR Service capabilities through the Employee Portal and supported collaboration channels. The Employee Experience for Public Sector Solutions add-on is required.",tags:["Employee2","Employment","Case"],docs:["HR Service provides employee service capabilities for efficiently addressing employee queries and service requests. Government employees can use HR Service subagents from the Employee Experience portal, Slack, or Microsoft Teams to complete routine tasks within their workflow. Supported subagents for platform users include Direct Deposit Management, Leave Management, Expense Management, Profile Management, and Enablement Programs.","To get started with HR Service in Public Sector Solutions, create an Employee user and select Lightning Platform during the User License and Profile step. For Public Sector Solutions, assign the Lightning Platform - One App user license instead of the Unified Employee License referenced in general HR Service guidance. Complete the standard HR Service subagent setup and populate the UserId lookup on each Employee2 record with the corresponding platform user record."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_employee_experience_for_pss.htm&type=5&language=en_US",connections:[{"planet":"common_features","desc":"Case management infrastructure shared with constituent-facing processes"},{"planet":"setup_and_security","desc":"Lightning Platform license and permission set assignment for employees"}]},
    {id:"it-service-integration",name:"Agentforce IT Service",icon:"\u{1F5A5}",desc:"Agentforce IT Service standardizes IT support delivery for government employees across Slack, Microsoft Teams, an Experience Cloud site, email, and chat. It combines AI, process automation, and human agents to provide personalized and consistent support. Agencies can use it to track incidents, process service requests, and manage problems, changes, and releases. The Employee Experience for Public Sector Solutions add-on is required.",tags:["Case","Employee2"],docs:["Agentforce IT Service helps agencies optimize IT operations, reduce costs, and improve public-service efficiency while supporting compliance and risk reduction. Employees can request assistance through Slack, Microsoft Teams, an Experience Cloud site, email, or chat. AI and human agents work together to provide support across these channels.","To use Agentforce IT Service with Public Sector Solutions, create an Employee user and select Lightning Platform during the User License and Profile step. Assign the Lightning Platform - One App user license instead of the Unified Employee License referenced in general Agentforce IT Service guidance. Complete the Agentforce IT Service basic setup and assign the applicable Agentforce IT Service permission sets."],connections:[{"planet":"agentforce","desc":"AI agents handle routine IT support requests automatically"},{"planet":"einstein_ai","desc":"AI-powered incident classification and service request routing"}]},
    {id:"employee-portal-access",name:"Employee Portal & Permissions",icon:"\u{1F511}",desc:"Employee Portal & Permissions provides authenticated employee access to HR Service, Agentforce IT Service, and Public Sector Solutions capabilities through Experience Cloud sites. Public Sector Solutions includes prebuilt site templates for the Employee Portal, Licenses and Permits, and Employee Site for Recruitment. Access is controlled through platform licenses, the Employee_Experience_User permission set group, and capability-specific permission sets. Employees also require access to the Case object in Lightning Experience when using Public Sector Solutions and HR Service capabilities there.",tags:["PersonEmployment","Employee2"],docs:["Set up employee-facing experiences by creating sites from the appropriate Experience Cloud templates. The Employee Portal exposes employee service capabilities, the Licenses and Permits template supports license-needs assessment and application tracking, and the Employee Site for Recruitment supports requisition approval and applicant evaluation. Console apps can also be created in Lightning Experience for internal workflows.","For Public Sector Solutions capabilities, make sure each employee has the Salesforce Platform user license and grant access to the Case object in Lightning Experience. Assign the Employee_Experience_User permission set group to provide common employee capabilities, or assign its permission sets individually according to employee responsibilities. The group includes access for Dynamic Assessments, program and case management, case proceedings, Criteria-Based Search and Filter, evidence management, licensing and permitting, grantmaking, and Outcome Management.","Some capabilities require permission sets outside the Employee_Experience_User permission set group. Talent Recruitment Management access is provided through Talent Recruitment Management Employee Access or Talent Recruitment Management Hiring Manager Access, depending on the employee's role. Agentforce Company Community Permissions for Public Sector provides employee access to supported Job Recommendation, Complaint Intake, and Benefit Assistance agents."],connections:[{"planet":"experience_cloud","desc":"Employee-facing portals built on Experience Cloud site templates"},{"planet":"talent_recruitment","desc":"Employee site for hiring managers and interviewer evaluations"}]},
    {id:"employee-pss-capabilities",name:"Employee PSS Capabilities",icon:"\u{2699}",desc:"Employee PSS Capabilities extends Public Sector Solutions workflows to government employees rather than limiting them to external constituents. Employees can use supported processes for benefits, grants, inspections, licenses and permits, provider services, and talent recruitment. Supervisors, hiring managers, interviewers, and other employees receive access according to their responsibilities. Experience Cloud sites and Lightning Experience provide the interfaces for these workflows.",tags:["PersonEmployment","Employment","Employee2"],docs:["Benefits Management allows employees to apply for and enroll in agency benefits, while Grants Management supports applications for education, research, and other grants. Inspections Management supports internal audits and compliance or safety inspections. License and Permit Management enables agencies to issue licenses, permits, certifications, accreditation, and other authorizations to employees.","Provider Management helps employees find providers that deliver training, counseling, or other services. Program and case management permissions can allow supervisors to create care plans and assign benefits and goals, while employees can view their care plans, benefits, and goals. Dynamic Assessments can be administered by supervisors and completed by employees through the employee experience.","Talent Recruitment Management supports internal candidates and the employees involved in hiring. The Employee Site for Recruitment lets hiring managers review and approve recruitment requisitions and job postings, while hiring managers and interviewers evaluate assigned applicants. The broader Employee Experience portal can also provide job search, application submission, document upload, draft saving, application tracking, Path Assistant updates, and Einstein Summary for internal application review."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.psc_employee_experience_for_pss.htm&type=5&language=en_US",connections:[{"planet":"benefit_management","desc":"Employees apply for and enroll in agency benefit programs"},{"planet":"grantmaking","desc":"Employees apply for education, research, and other grants"}]}
  ],
  dataFlow: ["Provision employee users with the applicable Lightning Platform license and configure permission sets through Public Sector Solutions setup and security.","Publish Experience Cloud sites for employee HR, IT, licensing, and recruitment workflows.","Accept HR and IT requests through the Employee Experience portal, Slack, Microsoft Teams, email, or chat, and use Agentforce agents where configured.","Route HR Service requests and Agentforce IT Service incidents to automated processes, AI agents, or human agents for resolution.","Enable employees to apply for and manage benefits and grants and to use inspections, licensing, and provider-management capabilities in Public Sector Solutions.","Support internal candidates, hiring managers, and interviewers through Talent Recruitment Management workflows and its employee site."],
  connections: [{"planet":"experience_cloud","desc":"Employee-facing portals for HR, IT, and PSS capabilities"},{"planet":"talent_recruitment","desc":"Internal candidates and hiring manager workflows"},{"planet":"benefit_management","desc":"Employee benefit enrollment and management"},{"planet":"grantmaking","desc":"Employee grant applications for education and research"},{"planet":"agentforce","desc":"AI agents for employee HR and IT support"},{"planet":"setup_and_security","desc":"Lightning Platform licensing and permission set configuration"}]
},

grantmaking: {
  packages: ["core"],
  name: "Grantmaking",
  icon: "\u{1F3C6}",
  color: "#f472b6",
  description: "Public Sector Solutions manages the complete grant lifecycle, including funding opportunities, budgets, applications, reviews, funding awards, Funding Disbursements, recipient requirements, and outcome measurement. Experience Cloud provides grantseeker and reviewer portals, and Employee Experience enables employees to apply for education and research grants. Action Plans, document checklists, stage management, and Form Framework support repeatable workflows, while Einstein generative AI provides application summaries, funding award summaries, and board versions of applications. Shared Benefit Management patterns support payment and outcome processes, grant outcome indicators can align with social program goals, and the Grantmaking data bundle maps Public Sector Solutions records to Data 360 for unified analytics.",
  components: [
    {id:"funding-opportunities",name:"Funding Opportunities",icon:"\u{1F4E2}",desc:"Funding Opportunities support the creation and management of grant programs in Public Sector Solutions. Grantmakers publish opportunity details, application instructions, available funding, status, and an associated budget template for prospective applicants. Grantseekers can discover opportunities through an Experience Cloud site and begin the related funding application process.",tags:["FundingOpportunity"],docs:["Funding opportunities establish the grant programs for which grantseekers can apply. Grantmakers define the opportunity, provide application instructions, identify the available funding, and associate a budget template with the opportunity. Public Sector Solutions supports the Grantmaking_Manager persona for users who create and manage funding opportunities and grant submissions.","An Experience Cloud site provides the grantseeker-facing experience for discovering funding opportunities and applying for grants. The Grantmaking_Applicant persona supports grantseekers who find and apply for opportunities and later report on funding and budgets. Compliant Data Sharing can control internal and external access to Funding Opportunity and related grantmaking records."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.grmk_grantmaking.htm&type=5&language=en_US",connections:[{"planet":"experience_cloud","desc":"Funding opportunities published on the Grantmaking Experience Cloud site"},{"planet":"einstein_ai","desc":"Einstein generates board versions of grant applications for review"}]},
    {id:"grant-budget-management",name:"Budget Management",icon:"\u{1F4B0}",desc:"Budget Management supports budget proposals, allocations, and spending tracking throughout the grant lifecycle. Budgets can be associated with funding opportunities and funding awards, while Budget Allocation records organize amounts for defined categories and periods. Grantmakers and grantseekers use these records to manage proposed funding and monitor actual budget spending.",tags:["Budget","BudgetAllocation"],docs:["Public Sector Solutions uses Budget and Budget Allocation records to manage grant budgets. A budget captures its amount, applicable dates, status, and related funding opportunity. Budget allocations divide that budget into amounts associated with category and period names.","Grantmaking includes processes to manage budget proposals and allocations and to track actual budget spending. Form Framework can present budget information with application details, decisions, and funding awards on related records. Compliant Data Sharing can provide role-based access to Budget records for internal grantmakers and external participants."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.grmk_grantmaking.htm&type=5&language=en_US",connections:[{"planet":"common_features","desc":"Budget tracking integrates with action plan milestones and document checklists"},{"planet":"experience_cloud","desc":"Grant seekers enter and track budgets through the Experience Cloud portal"}]},
    {id:"grant-applications-reviews",name:"Applications & Reviews",icon:"\u{1F4DD}",desc:"Applications & Reviews supports grant intake, evaluation, and decision-making in Public Sector Solutions. Form Framework provides multiphase and multisection applications, reusable intake form sections, progress report forms, and reviewer workspaces. Experience Cloud supports grantseeker submissions and external reviewer access, while Application Form Evaluation records capture reviewer decisions, ratings, and comments.",tags:["ApplicationForm","ApplicationFormRelation","ApplicationFormEvaluation","ApplicationFormEvalPtcp"],docs:["Form Framework simplifies funding applications by breaking long or complex forms into smaller sections that applicants can complete in phases. Sections can be reused across forms, and ad hoc sections can be added to applications that are in progress or already submitted. Grantseekers can complete these forms through an Experience Cloud site and later use progress report forms to report on grants.","Reviewer workspaces let reviewers evaluate applications and make decisions on one page. Application Form Evaluation records can capture the reviewer, decision, rating, and comments associated with an application form. Compliant Data Sharing supports controlled access to Application Form Evaluation and related application records for internal participants and external reviewers.","Action Plans can track application review steps, while Document Checklist Items route supporting documents through review workflows. Stage Management for Grantmaking can improve the accuracy and compliance of grant processes, and Dynamic Assessments can support grantmaking evaluations and audits. Einstein generative AI can produce application summaries and a Board Version of Grant Application to help reviewers and board members examine key application information."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.grmk_grantmaking.htm&type=5&language=en_US",connections:[{"planet":"common_features","desc":"Action plan templates manage repeatable review and approval tasks"},{"planet":"einstein_ai","desc":"Einstein summarizes application history and compares application versions"}]},
    {id:"funding-awards",name:"Funding Awards",icon:"\u{1F3C5}",desc:"Funding Awards represent approved grant funding and connect the awarded amount and contract period to the originating funding opportunity. Public Sector Solutions supports management of awards, related requirements, budgets, and recipient reporting after approval. Grantmakers can also use generated agreements and award summaries to administer and monitor awarded grants.",tags:["FundingAward","FundingAwardRequirement"],docs:["A Funding Award records the opportunity that produced the award, the awarded amount, contract dates, status, and associated budget. Funding Award Requirement records capture scheduled obligations for the award, including the requirement type, scheduled date, and status. Public Sector Solutions can automatically create recurring Funding Award Requirements for repeatable recipient obligations.","Grant agreements can be created with Omnistudio Document Generation, and the contract lifecycle can be managed with Salesforce Contracts. Funding awards are also supported as financial transactions in Accounting Subledger, where they can be mapped to Accounting Subledger objects and transferred to an accounting system. Einstein Funding Award Summary uses Funding Award, Funding Award Requirement, Funding Disbursement, Funding Opportunity, Indicator Performance Period, and Indicator Results data to help program officers assess grant health."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.grmk_grantmaking.htm&type=5&language=en_US",connections:[{"planet":"experience_cloud","desc":"Grant recipients track awards and submit reports through the portal"},{"planet":"common_features","desc":"Stage Management automates award lifecycle transitions"}]},
    {id:"grant-disbursements",name:"Disbursements",icon:"\u{1F4B8}",desc:"Disbursements support the release and monitoring of funds associated with awarded grants. Public Sector Solutions identifies the grant-payment scheduling entity as Funding Disbursement and supports automatic creation of recurring disbursements. Payment Request and Payment Request Line are separate records used as inputs to outbound-payment processing and are not identified as the grant disbursement records.",tags:["PaymentRequest","PaymentRequestLine"],docs:["Grantmakers use Funding Disbursement records to track grant payments after an award is established. Public Sector Solutions supports automatically creating recurring disbursements for repeatable award payments. Funding Disbursement is also a source object used by the Einstein Funding Award Summary when evaluating award progress and grant health.","Outbound Payments separately generates payment instructions when an approved Payment Request meets configured flow criteria. Those payment instructions are sent to an Enterprise Resource Planning system, and completed transaction details can be returned to Salesforce for reconciliation. This outbound-payment pattern also supports approved claims and Benefit Disbursement records, reflecting shared payment-processing patterns with Benefit Management without redefining Payment Request as a grant disbursement."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.grmk_grantmaking.htm&type=5&language=en_US",connections:[{"planet":"benefit_management","desc":"Disbursement patterns shared with benefit disbursement infrastructure"},{"planet":"common_features","desc":"Document checklists ensure required materials accompany disbursement requests"}]},
    {id:"grant-outcomes",name:"Outcome Management",icon:"\u{1F4CF}",desc:"Outcome Management helps grantmakers define an impact strategy and evaluate whether funded programs achieve their intended outcomes. Public Sector Solutions supports collecting data, tracking progress, and using actionable insights to assess grant performance. Outcome indicators can align grant activity with program goals and provide a basis for recipient progress reporting and program adjustments.",tags:["FundingAward","FundingAwardRequirement"],docs:["Outcome Management provides a structured way to define intended change and measure whether programs and grants achieve it. For example, an agency can measure how many unhoused people receive shelter through a housing grant and adjust the program or grant amount based on the results. Grantmakers can use this information to determine whether funded work is being delivered as planned and is producing its intended impact.","Grant recipients can report progress against goals and KPIs through an Experience Cloud site, and Form Framework supports progress report forms that reviewers can review and approve in a single view. Outcome indicators can be aligned with social program goals to connect grant performance to broader program objectives. The Grantmaking data bundle maps Public Sector Solutions data to Data 360 for unified analytics across grantmaking records and related outcome information."],docUrl:"https://help.salesforce.com/s/articleView?id=ind.grmk_grantmaking.htm&type=5&language=en_US",connections:[{"planet":"social_programs","desc":"Outcome indicators shared across grant and social program measurement"},{"planet":"experience_cloud","desc":"Grantees report outcomes and indicator results through the portal"}]}
  ],
  dataFlow: ["Create a funding opportunity and define its instructions, available funding, status, and budget template.","Publish the opportunity through Experience Cloud for grantseekers to complete and submit applications (employee education/research grants are handled separately by Grants Management under Employee Experience).","Review applications with Form Framework, Action Plans, document checklists, stage management, external reviewers, and Einstein-generated summaries or board versions.","Create the funding award, associate its budget, generate recurring requirements, and schedule payments as Funding Disbursements.","Collect recipient progress reports, measure outcome indicators against program goals, and unify grantmaking data in Data 360 for analytics."],
  connections: [{"planet":"experience_cloud","desc":"Grant seeker and reviewer portal for applications and reporting"},{"planet":"common_features","desc":"Action plans, document checklists, and stage management for grant workflows"},{"planet":"einstein_ai","desc":"AI-generated application summaries, award summaries, and board versions"},{"planet":"benefit_management","desc":"Shared disbursement and outcome measurement patterns"},{"planet":"social_programs","desc":"Grant outcome indicators aligned with program goals"},{"planet":"data_360","desc":"Grantmaking data bundle maps objects to Data Cloud for unified analytics"},{"planet":"employee_experience","desc":"Employees apply for education and research grants"}]
}

};
